    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return cmd
    # Local imports (do not add module-level imports)
    import os

    cmd_list = list(cmd)
    first = cmd_list[0]

    # Handle a lone '#!' indicator (unlikely but defensive)
    if first == "#!":
        return tuple(cmd_list[1:])

    # If first element is a file path that exists, try to detect a shebang
    if isinstance(first, str) and os.path.isfile(first):
        # Only bother with python scripts (.py, .pyw)
        _, ext = os.path.splitext(first)
        if ext.lower() in {".py", ".pyw"}:
            interpreter = "python"  # default
            try:
                with open(first, "rb") as f:
                    line = f.readline().decode(errors="ignore")
                if line.startswith("#!"):
                    # split first line on whitespace, ignoring '#!'
                    parts = line[2:].strip().split()
                    if parts:
                        # choose interpreter if it looks like python
                        base = os.path.basename(parts[0]).lower()
                        if base in {"python", "pythonw", "python.exe", "pythonw.exe"}:
                            interpreter = parts[0]
                        else:
                            interpreter = "python"
                else:
                    interpreter = "python"
            except Exception:
                interpreter = "python"

            # Convert script path to absolute to avoid relative ambiguities
            abs_path = os.path.abspath(first)
            cmd_list = [interpreter, abs_path] + cmd_list[1:]

    return tuple(cmd_list)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os, sys

    # Only apply fixes on Windows
    if not sys.platform.startswith("win"):
        return cmd

    parts = list(cmd)
    if not parts:
        return cmd

    first = parts[0]

    # If the command is a python script, prepend python interpreter
    ext = os.path.splitext(first)[1].lower()
    if ext in {".py", ".pyw"}:
        return (sys.executable, "-u", first) + tuple(parts[1:])

    # Try to detect a shebang that refers to a python interpreter
    try:
        with open(first, "rb") as f:
            first_line = f.readline().decode(errors="ignore")
        if first_line.startswith("#!") and "python" in first_line.lower():
            return (sys.executable, "-u", first) + tuple(parts[1:])
    except Exception:
        pass

    # Return the original command if no adjustments were made
    return tuple(parts)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    sys = __import__('sys')
    os = __import__('os')

    # Only need to care about Windows platforms
    if not sys.platform.lower().startswith('win'):
        return cmd

    # Handle shebangs: `#!interpreter args...`
    if cmd and cmd[0].startswith('#!'):
        shebang = cmd[0][2:].strip()
        if shebang:
            parts = shebang.split()
            interpreter = parts[0]
            # Resolve relative interpreter path
            if not os.path.isabs(interpreter):
                interpreter = os.path.abspath(interpreter)
            # Quote if required
            if ' ' in interpreter and not (interpreter.startswith('"') and interpreter.endswith('"')):
                interpreter = f'"{interpreter}"'
            rest = tuple(parts[1:])
            # Build new command: interpreter + any args from shebang + remaining cmd args
            new_cmd = (interpreter, *rest)
            if len(cmd) > 1:
                new_cmd += cmd[1:]
            return new_cmd
        else:
            # Empty shebang, skip it
            return tuple(cmd[1:])

    # Normalise each argument that looks like a path
    new_cmd = []
    for arg in cmd:
        if isinstance(arg, str) and os.path.exists(arg):
            abs_path = os.path.abspath(arg)
            # Quote if path contains whitespace
            if ' ' in abs_path and not (abs_path.startswith('"') and abs_path.endswith('"')):
                abs_path = f'"{abs_path}"'
            new_cmd.append(abs_path)
        else:
            new_cmd.append(arg)
    return tuple(new_cmd)

