def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Build adjacency list and indegree count
    out_edges = {}
    indegree = {}
    appearance = {}
    next_index = 0

    for seq in orderings:
        for i, node in enumerate(seq):
            if node not in indegree:
                indegree[node] = 0
                out_edges[node] = set()
            if node not in appearance:
                appearance[node] = next_index
                next_index += 1
            if i > 0:
                prev = seq[i - 1]
                if node not in out_edges[prev]:
                    out_edges[prev].add(node)
                    indegree[node] += 1

    # Perform Kahn's algorithm with deterministic tie‑breaking
    zero_nodes = [node for node, deg in indegree.items() if deg == 0]
    # Sort by first appearance to preserve original relative order
    zero_nodes.sort(key=lambda n: appearance[n])
    result = []

    while zero_nodes:
        current = zero_nodes.pop(0)
        result.append(current)
        for succ in out_edges[current]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                # insert while maintaining appearance order
                inserted = False
                for idx, node in enumerate(zero_nodes):
                    if appearance[succ] < appearance[node]:
                        zero_nodes.insert(idx, succ)
                        inserted = True
                        break
                if not inserted:
                    zero_nodes.append(succ)

    if len(result) != len(appearance):
        raise ValueError("Cycle detected or missing nodes in ordering merge")

    return result

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Determine which classes are not superclasses of any other class in the list
    minimal = set()
    for cls in classes:
        if not any(issubclass(d, cls) and d is not cls for d in classes):
            minimal.add(cls)
    # Preserve the original order while keeping only the minimal classes
    return [cls for cls in classes if cls in minimal]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if not any(issubclass(cls, other) and cls != other for other in classes):
            minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        if cls is None:
            continue
        # Skip if already covered by a more general class
        if any(issubclass(cls, existing) for existing in minimal):
            continue
        # Remove any existing classes that are subclasses of the new one
        minimal = [existing for existing in minimal if not issubclass(existing, cls)]
        minimal.append(cls)
    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = []
    for name in dir(self):
        # Skip private/special attributes
        if name.startswith('_'):
            continue
        value = getattr(self, name, None)
        # Skip methods and callable objects
        if callable(value):
            continue
        # Try to fetch the attribute's docstring
        doc = None
        cls_attr = getattr(type(self), name, None)
        if hasattr(cls_attr, '__doc__'):
            doc = cls_attr.__doc__
        elif hasattr(value, '__doc__'):
            doc = value.__doc__
        if all:
            result.append((name, doc, value))
        else:
            result.append((name, doc))
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    for name in dir(self):
        if name.startswith('_') and not all:
            continue
        if not hasattr(self, name):
            continue
        attr = getattr(self, name)
        if callable(attr):
            continue
        desc = None
        cls_attr = getattr(self.__class__, name, None)
        if cls_attr and hasattr(cls_attr, "__doc__"):
            desc = cls_attr.__doc__
        if desc is None and hasattr(attr, "__doc__"):
            desc = attr.__doc__
        result[name] = desc
    return result

