    import inspect
    result = []
    for name, obj in inspect.getmembers(self.__class__):
        if name.startswith('_'):
            continue
        desc = getattr(obj, '__doc__', None)
        if all or desc:
            result.append((name, desc))
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    cls_dict = vars(self.__class__)
    if all:
        return [name for name, val in cls_dict.items() if not callable(val)]
    else:
        return [name for name, val in cls_dict.items()
                if not callable(val) and not name.startswith('_')]

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # We collect the simple attribute names that are not private (start with _)
    # and are not callables.  If ``all`` is True we include class-level attributes
    # inherited via MRO, otherwise we return only instance attributes.
    if all:
        attrs = set()
        for cls in self.__class__.__mro__:
            for name, val in cls.__dict__.items():
                if name.startswith('_'):
                    continue
                if callable(val):
                    continue
                attrs.add(name)
        # Include instance attributes as well
        for name in self.__dict__:
            if name.startswith('_'):
                continue
            attrs.add(name)
        return sorted(attrs)
    else:
        result = []
        for name in self.__dict__:
            if name.startswith('_'):
                continue
            result.append(name)
        return sorted(result)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.
    Anything but indiviudal interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    if sequence is None:
        return output

    for item in sequence:
        # Expand tuples or iterables (but keep strings and other single
        # interfaces untouched)
        if isinstance(item, (list, tuple)):
            output = _normalizeargs(item, output)
        else:
            output.append(item)

    return output

