def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context tracking structure
        self.context = {}

        # Reinitialize bins
        try:
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # Preserve the original bin structure but reset values
                for key in list(self.bins.keys()):
                    self.bins[key] = self.initial_value
            else:
                # Create a fresh set of bins as defined by the class
                self.bins = self.make_bins()
        except AttributeError:
            # If either 'bins' or 'make_bins' is missing, raise a clear error
            raise RuntimeError("Histogram object lacks required attributes 'bins' or 'make_bins'")

