def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
           Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Gather the rows of the CSV
    rows = []

    # Optional header line
    if header is not None:
        rows.append(header)

    # Iterate over the graph points.  We try several common ways to
    # access the coordinates and values.
    #  - If the graph implements an ``iterpoints`` method we use that.
    #  - Otherwise we fall back to iterating over ``self`` itself,
    #    expecting (args, value) pairs.
    #  - If the graph stores points in a ``points`` dict (`index`),
    #    we use that.

    # Helper to convert a value (which may be an iterable) to a string.
    def value_to_string(val):
        if isinstance(val, (list, tuple, set)):
            try:
                return separator.join(map(str, val))
            except Exception:
                return str(val)
        else:
            return str(val)

    # Main iteration
    try:
        # First, try iterpoints – some graph types expose this.
        it = getattr(self, "iterpoints", lambda: iter(self))()
    except Exception:
        # If that fails, just fall back to iterating over `self`.
        it = iter(self)

    for point in it:
        # Extracting coordinates and data varies across graph implementations.
        try:
            # Common pattern: point has `args` or `coords` attribute.
            if hasattr(point, "args"):
                coords = value_to_string(point.args)
            elif hasattr(point, "coords"):
                coords = value_to_string(point.coords)
            else:
                # Assume the point itself is the coordinate tuple.
                coords = value_to_string(point)
        except Exception:
            # If anything goes wrong just use the raw point.
            coords = value_to_string(point)

        # Fetch the value associated with the point.
        # Some implementations store it in `data`,
        # others in `value`, or via a method.
        try:
            if hasattr(point, "data"):
                val = point.data
            elif hasattr(point, "value"):
                val = point.value
            else:
                # If point is not an object, try treating it as key in self (dict)
                val = self[point] if hasattr(self, "__getitem__") else None
        except Exception:
            val = None

        # Convert the value to a string representation.
        val_str = value_to_string(val)

        # Combine coordinate and value strings.
        if val_str:
            line = separator.join([coords, val_str])
        else:
            line = coords

        rows.append(line)

    # Return the joined CSV string.
    return "\n".join(rows)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the error indices for the given coordinate name from the
    # instance's error mapping. If the mapping is missing or the coordinate
    # is not present, return an empty list.
    err_map = getattr(self, 'err_indices', None)
    if err_map is None:
        return []
    return list(err_map.get(coord_name, []))

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Accept a string or a coordinate object that has a ``name`` attribute
    if not isinstance(coord_name, str) and hasattr(coord_name, "name"):
        coord_name = coord_name.name

    # The instance may store the indices in an internal dictionary called
    # ``_err_indices``.  If that attribute is missing we simply return an
    # empty list.
    if hasattr(self, "_err_indices"):
        return list(self._err_indices.get(coord_name, []))
    return []

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Determine where to store error entries
        if isinstance(context, dict):
            error_ctx = context.setdefault('error', {})
        else:
            error_ctx = getattr(context, 'error', None)
            if error_ctx is None:
                error_ctx = {}
                setattr(context, 'error', error_ctx)

        # Retrieve field names and coordinate names if available
        field_names = getattr(self, 'fieldnames', None)
        if field_names is None:
            field_names = getattr(self, 'fields', None)
        if field_names is None:
            field_names = []

        coord_names = getattr(self, 'coordinates', None)
        if coord_names is None:
            coord_names = []

        coord_mapper = {}
        for i, cname in enumerate(coord_names[:3]):  # only first three
            if i < 3:
                coord_mapper[cname] = chr(ord('x') + i)

        for idx, fname in enumerate(field_names):
            if not fname.startswith('error_'):
                continue
            err_suffix = fname[len('error_'):]

            # Split the suffix into coordinate part and anything after underscore
            parts = err_suffix.split('_', 1)
            if len(parts) == 2:
                coord_part, rest = parts
            else:
                coord_part = parts[0]
                rest = ''

            # Map coordinate name to x/y/z if possible
            coord_letter = coord_mapper.get(coord_part)
            if coord_letter is None:
                # Try to guess by first letter of the coordinate part
                if coord_part:
                    coord_letter = coord_part[0].lower()
                else:
                    coord_letter = ''

            err_name = f"{coord_letter}_{rest}" if rest else coord_letter

            # Store the index, preserving existing value structure
            if err_name in error_ctx:
                # If already set, keep original (do not overwrite)
                pass
            else:
                error_ctx[err_name] = {'index': idx}

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(edges) - 1 != len(bins):
        raise ValueError("Number of edges must be one more than number of bins")
    widths = [edges[i+1] - edges[i] for i in range(len(bins))]
    return sum(b * w for b, w in zip(bins, widths))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
