        for k, v in sub_d1.items():
            if k not in sub_d2:
                # value not in d2, include it
                out[k] = v
                continue

            w = sub_d2[k]
            # If both values are dicts and we can recurse
            if isinstance(v, dict) and isinstance(w, dict) and sub_level != 0:
                # Determine recursion depth
                new_level = sub_level - 1 if sub_level > 0 else -1
                sub_res = _diff(v, w, new_level)
                if sub_res:
                    out[k] = sub_res
                # If sub_res empty, nothing to add
            else:
                # Values differ, include v
                if v != w:
                    out[k] = v
        return out

    # Kick off recursion
    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _deepcopy(obj):
        if isinstance(obj, dict):
            return {k: _deepcopy(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_deepcopy(v) for v in obj]
        if isinstance(obj, tuple):
            return tuple(_deepcopy(v) for v in obj)
        if isinstance(obj, set):
            return {_deepcopy(v) for v in obj}
        return obj

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError('difference only works with dictionaries')

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            result[key] = _deepcopy(val1)
        else:
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                if level == 0:
                    if val1 != val2:
                        result[key] = _deepcopy(val1)
                else:
                    subdiff = difference(val1, val2, level - 1 if level > 0 else level)
                    if subdiff:
                        result[key] = subdiff
            else:
                if val1 != val2:
                    result[key] = _deepcopy(val1)
    return result

