        for k, v in src.items():
            if k not in tgt:
                result[k] = v
            else:
                tv = tgt[k]
                if isinstance(v, dict) and isinstance(tv, dict):
                    if cur_level != 0:
                        # deeper recursion; keep infinite level as -1
                        sub_lvl = cur_level - 1 if cur_level > 0 else -1
                        sub = _diff(v, tv, sub_lvl)
                        if sub:
                            result[k] = sub
                    else:
                        # max depth reached: treat whole dict as diff if not equal
                        if v != tv:
                            result[k] = v
                else:
                    if v != tv:
                        result[k] = v
        return result

