       add keyword argument *level*.
    """
    # helper to decide the next recursion level
    def _next_lvl(lvl):
        return -1 if lvl == -1 else lvl - 1

    result = {}
    for key, val in d1.items():
        if key not in d2:
            # key absent in d2 – copy value (deep copy for dicts)
            if isinstance(val, dict):
