            else:
                if val != val2:
                    result[key] = val
    return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure the coordinate is a sequence of the right dimensionality
    try:
        coords = list(coord)
    except TypeError:
        coords = [coord]

    if len(coords) != len(self.edges):
        raise ValueError("Coordinate dimensionality must match histogram edges")

    # Determine whether each coordinate lies inside the valid area
    idx = []
    for dim, c in enumerate(coords):
        # If the coordinate is outside the edge range, ignore it
        if c < self.edges[dim][0] or c >= self.edges[dim][-1]:
            return  # outside → ignore
        # Find the bin index for this axis using binary search
        lo, hi = 0, len(self.edges[dim]) - 1
        while lo < hi - 1:
            mid = (lo + hi) // 2
            if c < self.edges[dim][mid]:
                hi = mid
            else:
                lo = mid
        idx.append(lo)

    # Increment the bin value by the given weight
    try:
        self.bins[tuple(idx)] += weight
    except Exception as e:
        # If the indexing fails for any reason, simply ignore the data point
        pass

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Ensure coord is iterable (works for single- or multi-dimensional histograms)
        try:
            values = tuple(coord)
        except TypeError:
            values = (coord,)

        # Determine indices for each dimension
        indices = []
        for dim, val in enumerate(values):
            # Get edges for this dimension (support both list/tuple of arrays and a single numpy array)
            if isinstance(self.edges, (list, tuple)):
                edges = self.edges[dim]
            else:
                edges = self.edges
            # Find bin index: searchsorted returns index where val could be inserted
            bin_idx = np.searchsorted(edges, val, side='right') - 1
            # Check if coordinate is outside the valid range
            if bin_idx < 0 or bin_idx >= len(edges) - 1:
                # outside histogram edges; ignore
                return
            indices.append(bin_idx)

        # Increment the bin content
        try:
            self.contents[tuple(indices)] += weight
        except AttributeError:
            # Fallback if histogram stores values in a different attribute
            if hasattr(self, 'buckets'):
                self.buckets[tuple(indices)] += weight
            else:
                raise AttributeError("Histogram object has no 'contents' or 'buckets' attribute to store bin counts.")

