    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    def _handle_value(key, value, orig_value):
        if isinstance(value, dict):
            # recurse into nested dict
            return generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # preserve list structure, but replace elements that are not dict/list with None
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    # nested list; recurse
                    new_list.append(_handle_value(key, item, value))
                else:
                    new_list.append(None)
            return new_list
        else:
            # non-dict, non-list -> replace with None
            return None

    result = {}
    for k, v in manifest_dict.items():
        result[k] = _handle_value(k, v, v)

    if first_level:
        # Copy common identifying fields from the original manifest
        metadata = manifest_dict.get("metadata")
        if isinstance(metadata, dict):
            meta_copy = result.setdefault("metadata", {})
            # Copy 'name' and 'namespace' fields if present
            if "name" in metadata:
                meta_copy["name"] = metadata["name"]
            if "namespace" in metadata:
                meta_copy["namespace"] = metadata["namespace"]
            # The rest of the metadata keys remain as None or empty dicts
            if "labels" in metadata:
                # preserve the labels dictionary structure but nullify its values
                meta_copy.setdefault("labels", {k: None for k in metadata["labels"]})
            if "annotations" in metadata:
                meta_copy.setdefault("annotations",
                                     {k: None for k in metadata["annotations"]})
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
