    non-list and non-dict values by ``None``.  In case of ``first_level`` dictionary
    (i.e. complete ``observer_schema`` for a resource), the values of the identifying
    fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")

    result = {}

    # Define hand‑copy fields for the top level (all findable identifiers)
    id_fields = ["apiVersion", "kind", "metadata"]

    for key, value in manifest_dict.items():
        if first_level and key in id_fields:
            # Keep the original value for identifying fields
            result[key] = value
        else:
            # Replace non dict/list values with None
            if isinstance(value, dict):
                # Recurse into nested dict; no first_level flag
                result[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                processed_list = []
                for item in value:
                    if isinstance(item, dict):
                        processed_list.append(generate_default_observer_schema_dict(item, first_level=False))
                    else:
                        processed_list.append(None)
                result[key] = processed_list
            else:
                result[key] = None

    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest,
    observer_schema,
    response,
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema`` describing the
            fields that should be observed.
        response (dict): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Normalise input to list in case a single field string is provided
    if isinstance(observer_schema, str):
        observer_schema = [observer_schema]

    for spec in observer_schema:
        # Simple field specification represented as a string
        if isinstance(spec, str):
            field = spec
            if field not in last_applied_manifest and field in response:
                last_applied_manifest[field] = response[field]
            continue

        # Complex field specification represented as a dictionary
        if isinstance(spec, dict):
            field = spec.get("field") or spec.get("name") or spec.get("key")
            if not field:
                continue

            # Skip if the field does not exist in the response
            if field not in response:
                continue

            value = response[field]

            # Determine if there is a sub-schema to recurse into
            sub_schema = spec.get("sub_schema") or spec.get("subSchema") or spec.get("subSchemas")
            if sub_schema and isinstance(value, dict):
                # Initialise sub‑dict if missing
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[field], sub_schema, value
                )
                continue

            if sub_schema and isinstance(value, list):
                # Ensure we have a list in the manifest for this field
                if field not in last_applied_manifest or not isinstance(last_applied_manifest[field], list):
                    last_applied_manifest[field] = []
                # Extend the manifest list to match the response list
                while len(last_applied_manifest[field]) < len(value):
                    last_applied_manifest[field].append({})
                # Recursively update each item
                for idx, item in enumerate(value):
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[field][idx], sub_schema, item
                    )
                continue

            # If no sub_schema or not a complex structure, just set the value
            if field not in last_applied_manifest:
                last_applied_manifest[field] = value
    return

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_list_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields and initializes their value in
    ``last_applied_manifest`` if they are not yet present.
    """
    for key, schema in observer_schema.items():
        # The request must contain the field; otherwise we cannot continue
        if key not in response:
            raise KeyError(f"Missing expected field '{key}' in response")

        resp_value = response[key]

        # If the key is already present in the target manifest, we only need
        # to recurse into nested structures to fill missing sub‑values.
        if key not in last_applied_manifest:
            # Not present: create a placeholder according to the schema type
            if isinstance(schema, dict):
                last_applied_manifest[key] = {}
            elif isinstance(schema, list):
                # Assume a list of dicts with a single item schema
                last_applied_manifest[key] = []
            else:
                last_applied_manifest[key] = resp_value
                continue

        # Now we have a placeholder; descend in case of nested structures
        if isinstance(schema, dict) and isinstance(resp_value, dict):
            # Recurse into the nested dictionary
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema, resp_value
            )
        elif isinstance(schema, list) and isinstance(resp_value, list):
            # Handle a list of items
            # Determine child schema; it could be a dict or a list
            child_schema = schema[0] if schema else None
            # Ensure the list in the target has at least as many items as the
            # response. New items are created from the child_schema.
            while len(last_applied_manifest[key]) < len(resp_value):
                if isinstance(child_schema, dict):
                    last_applied_manifest[key].append({})
                else:
                    last_applied_manifest[key].append(None)
            # Recurse into each element
            for idx, item_resp in enumerate(resp_value):
                if item_resp is None:
                    continue
                if isinstance(child_schema, dict) and isinstance(item_resp, dict):
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[key][idx], child_schema, item_resp
                    )
                else:
                    # Primitive type: only set if not already present
                    if last_applied_manifest[key][idx] is None:
                        last_applied_manifest[key][idx] = item_resp
        else:
            # Primitive value: set only if still missing
            if last_applied_manifest[key] is None:
                last_applied_manifest[key] = resp_value
    # The function updates the dictionary in place. No return value is needed.

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in the response")

        # If the field is missing in the manifest, initialise it
        if key not in last_applied_manifest:
            if isinstance(sub_schema, dict):
                last_applied_manifest[key] = {}
                # Recurse into the nested dictionary
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )
            else:
                last_applied_manifest[key] = response[key]
        else:
            # If field is already present and is a dict, still recurse
            if (
                isinstance(sub_schema, dict)
                and isinstance(last_applied_manifest[key], dict)
                and isinstance(response[key], dict)
            ):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], sub_schema, response[key]
                )

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return

    for res in app.spec.manifest.values():
        # Skip if the resource already has an observer schema
        if getattr(res, "observer_schema", None) or res.get("observer_schema"):
            continue

        # Build a minimal default schema
        api_version = getattr(res, "apiVersion", None) or res.get("apiVersion", "v1")
        kind = getattr(res, "kind", None) or res.get("kind", "Resource")
        # Retrieve the name from metadata if possible
        if hasattr(res, "metadata") and isinstance(res.metadata, dict):
            name = res.metadata.get("name", None)
        else:
            name = res.get("metadata", {}).get("name", None)

        default_schema = {"apiVersion": api_version, "kind": kind}
        if name is not None:
            default_schema["metadata"] = {"name": name}

        # Attach the default schema back to the resource
        if isinstance(res, dict):
            res["observer_schema"] = default_schema
        else:
            setattr(res, "observer_schema", default_schema)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: Mapping from resource kind to its generated default observer schema.
    """
    # The result mapping from resource kind to the created default schema
    schemas = {}

    # Try to get the list of resources from the application's spec
    try:
        resources = getattr(app, "spec", None) and getattr(app.spec, "manifest", None)
    except AttributeError:
        resources = None

    # If no resources are available, just return an empty dict
    if not resources:
        return schemas

    # Helper to detect if a schema is already defined
    def has_custom_schema(resource):
        if isinstance(resource, dict):
            return "observer_schema" in resource or "custom_schema" in resource
        else:
            # object style
            return getattr(resource, "observer_schema", None) is not None or \
                   getattr(resource, "custom_schema", None) is not None

    # Helper to extract known information from a resource
    def get_resource_info(resource):
        if isinstance(resource, dict):
            kind = resource.get("kind") or resource.get("Kind")
            api_version = resource.get("apiVersion") or resource.get("API_VERSION")
            metadata = resource.get("metadata") or {}
            name = metadata.get("name")
        else:
            kind = getattr(resource, "kind", None) or getattr(resource, "Kind", None)
            api_version = getattr(resource, "api_version", None) or getattr(
                resource, "apiVersion", None) or getattr(resource, "API_VERSION", None)
            meta = getattr(resource, "metadata", None) or getattr(resource, "MetaData", None)
            name = getattr(meta, "name", None) if meta else None
        return kind, api_version, name

    for res in resources:
        # Skip resources that already declare a custom/observer schema
        if has_custom_schema(res):
            continue

        kind, api_version, name = get_resource_info(res)

        # Without a kind we cannot create a useful schema
        if not kind:
            continue

        # Build a minimal default observer schema
        default_schema = {
            "kind": kind,
            "apiVersion": api_version,
            "metadata": {}
        }
        if name:
            default_schema["metadata"]["name"] = name

        # Attach the default schema back to the resource
        if isinstance(res, dict):
            res["observer_schema"] = default_schema
        else:
            setattr(res, "observer_schema", default_schema)

        # Keep the schema in the result mapping; the last seen wins if duplicate kinds
        schemas[kind] = default_schema

    # Attach the mapping to the application if it accepts an `observer_schemas` attribute
    if hasattr(app, "observer_schemas"):
        app.observer_schemas.update(schemas)
    else:
        app.observer_schemas = schemas

    return schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Verify that the application has the expected attributes
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        raise ValueError("The application object does not contain spec.manifest.")

    # Ensure an observer_schema dictionary exists
    observer_schema = getattr(app.spec, "observer_schema", None)
    if observer_schema is None:
        app.spec.observer_schema = {}
        observer_schema = app.spec.observer_schema

    # Iterate over all resources in the manifest
    for resource in app.spec.manifest:
        kind = resource.get("kind")
        if not kind:
            continue

        # Only create a default schema if one hasn't been supplied already
        if kind not in observer_schema:
            # Generate a minimal placeholder schema for the resource
            default_schema = {
                "type": kind,
                "metadata": {
                    "name": resource.get("metadata", {}).get("name", ""),
                },
            }
            observer_schema[kind] = default_schema

    return app

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Basic validation: check for the presence of required files/directories
    try:
        import os
        required = {'.ocfl_version', 'objects', 'config.json'}
        if isinstance(path, str):
            if not os.path.isdir(path):
                return False
            existing = {name for name in os.listdir(path)}
            if not required.issubset(existing):
                return False
            return True
        else:
            # Assume a pyfs-like root with a listdir method
            if not hasattr(path, 'listdir'):
                return False
            existing = set(path.listdir())
            if not required.issubset(existing):
                return False
            return True
    except Exception:
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        head_path = os.path.join(path, "HEAD")
        if os.path.isfile(head_path):
            # Validate a single OCFL object
            rev_dirs = [d for d in os.listdir(path) if re.match(r"^[0-9a-f]{32}$", d)]
            if not rev_dirs:
                return False
            for rev in rev_dirs:
                rev_path = os.path.join(path, rev)
                if not os.path.isdir(rev_path):
                    return False
                content_dir = os.path.join(rev_path, "content")
                if not os.path.isdir(content_dir):
                    return False
            return True
        else:
            # Assume path is a pyfs root containing multiple OCFL objects
            all_valid = True
            for entry in os.listdir(path):
                entry_path = os.path.join(path, entry)
                if os.path.isdir(entry_path):
                    if not self.validate(entry_path):
                        all_valid = False
            return all_valid
    except Exception:
        return False

def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        import os

        # Decide if path is a string (filesystem path) or a pyfs root object
        try:
            # pyfs objects expose the `exists` method and work like a dictionary of paths
            has_exists = hasattr(path, 'exists')
        except Exception:
            has_exists = False

        # Helper to check existence of a required file
        def exists(file_path):
            if has_exists:
                return path.exists(file_path)
            else:
                return os.path.isfile(os.path.join(path, file_path))

        # Ensure the root is a directory (either fs root or filesystem)
        if has_exists:
            if not path.isdir('.'):
                return False
        else:
            if not os.path.isdir(path):
                return False

        # List of mandatory files for an OCFL object (simplified for this example)
        required_files = ['manifest.json', 'ocfl-version.txt']

        for file_name in required_files:
            if not exists(file_name):
                # Missing required file; validation fails
                return False

        # No fatal errors encountered; consider the object valid
        return True

