    # If the object does not have a log attribute, return an empty string
    if not hasattr(self, 'validation_log') or not getattr(self, 'validation_log'):
        return ''

    lines = []
    for entry in self.validation_log:
        # Entry may be a simple string
        if isinstance(entry, str):
            lines.append(f"{prefix}{entry}")
