def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Ensure inventory is a mapping
        if not isinstance(inventory, dict):
            raise TypeError("inventory must be a dictionary")

        # Extract spec version if requested
        spec_type = inventory.get("type")
        if extract_spec_version:
            if isinstance(spec_type, str):
                # Expect format like 'FoLiA-1.0' or 'FO-LIA-0.9'
                parts = spec_type.split("-", 1)
                if len(parts) == 2 and parts[0].lower() in ("folia", "fo-li-a"):
                    self.spec_version = parts[1]
                else:
                    # Fallback: keep whatever self.spec_version currently has
                    pass

        # Basic key checks – these are typical inventory fields
        required_keys = {"id", "type", "contents"}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(f"Inventory missing required keys: {', '.join(sorted(missing))}")

        # Validate field types
        if not isinstance(inventory["id"], str):
            raise TypeError("inventory['id'] must be a string")
        if not isinstance(inventory["type"], str):
            raise TypeError("inventory['type'] must be a string")
        if not isinstance(inventory["contents"], list):
            raise TypeError("inventory['contents'] should be a list")

        # Validate content items if structure known
        for idx, item in enumerate(inventory["contents"]):
            if not isinstance(item, dict):
                raise ValueError(f"contents[{idx}] is not a dict")
            if "label" not in item:
                raise ValueError(f"contents[{idx}] missing 'label' key")
            if not isinstance(item["label"], str):
                raise TypeError(f"contents[{idx}]['label'] must be a string")

        # Optional: apply spec_version specific checks
        if self.spec_version and self.spec_version.startswith("1."):
            # Example: version 1 requires a 'schema' key in each content item
            for idx, item in enumerate(inventory["contents"]):
                if "schema" not in item:
                    raise ValueError(f"contents[{idx}] missing required 'schema' key for spec_version 1.x")

        return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    errors = []

    # Determine the specification version
    spec_version = None
    if extract_spec_version and hasattr(inventory, 'type'):
        try:
            spec_version = int(inventory.type)
        except (ValueError, TypeError):
            spec_version = getattr(self, 'spec_version', None)
    else:
        spec_version = getattr(self, 'spec_version', None)

    if spec_version is None:
        errors.append('Specification version could not be determined.')

    # Starting simple sanity‐checks on the inventory
    ids_seen = set()
    items = getattr(inventory, 'items', None)
    if items is None or not isinstance(items, list):
        errors.append('Inventory does not contain a list of items (expected attribute `items`).')
        return {'valid': not errors, 'errors': errors}

    for index, item in enumerate(items):
        # Check that each item has an identifier
        if not hasattr(item, 'id'):
            errors.append(f'Item at position {index} has no `id` attribute.')
            continue

        # Duplicate id check
        if item.id in ids_seen:
            errors.append(f'Duplicate id `{item.id}` found in inventory (at position {index}).')
        else:
            ids_seen.add(item.id)

        # If the item has a type attribute, try to reconcile it with the spec_version
        if hasattr(item, 'type'):
            try:
                item_spec_version = int(item.type)
                if spec_version is not None and item_spec_version != spec_version:
                    errors.append(
                        f'Item `{item.id}` has type version {item_spec_version} '
                        f'which does not match inventory spec version {spec_version}.'
                    )
            except (ValueError, TypeError):
                # If conversion fails, just ignore – not a hard error
                pass

    # Return a simple validation report
    return {'valid': not errors, 'errors': errors}

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Collect all digests reported in the manifest
    manifest_digests = set()
    for f in manifest_files:
        # Try to get the digest from a dict or an object attribute
        if isinstance(f, dict):
            digest = f.get('digest')
        else:
            digest = getattr(f, 'digest', None)
        if digest:
            manifest_digests.add(digest)

    # 1) Ensure each digest required by the manifest is actually used
    missing = manifest_digests - set(digests_used)
    if missing:
        raise ValueError(
            f"The following digests are listed in the manifest but not used: {sorted(missing)}"
        )

    # 2) Ensure there are no digests claimed as used that are not present in the manifest
    unused = set(digests_used) - manifest_digests
    if unused:
        raise ValueError(
            f"The following digests are used but not defined in the manifest: {sorted(unused)}"
        )

    # If both checks pass, everything is consistent
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing = []
    unused = []

    for f in manifest_files:
        # Try to get a digest from common patterns
        digest = None
        if isinstance(f, dict):
            digest = f.get('digest')
        else:
            # attempt attribute access
            digest = getattr(f, 'digest', None)

        if not digest:
            continue  # nothing to check

        # Determine if digest is used, depending on the type of digests_used
        if isinstance(digests_used, dict):
            is_used = digests_used.get(digest, False)
        else:
            # assume a set or list of used digests
            is_used = digest in digests_used

        if not is_used:
            # check if it's missing from used collection
            if isinstance(digests_used, dict):
                if digest not in digests_used:
                    missing.append(digest)
                else:
                    unused.append(digest)
            else:
                missing.append(digest)

    if missing:
        raise ValueError(f"Digests missing from used list: {missing}")
    if unused:
        raise ValueError(f"Digests present but not marked as used: {unused}")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # The prior object must be a InventoryValidator (or subclass)
    assert isinstance(prior, InventoryValidator), "prior must be an InventoryValidator instance"

    # Inspect a simple 'version' attribute if present.  An older version
    # must have a version string that is *strictly* less than the current one.
    cur_ver = getattr(self.inventory, "version", None)
    prior_ver = getattr(prior.inventory, "version", None)
    if cur_ver is not None and prior_ver is not None:
        try:
            # naïve string compare; works for simple X.Y.Z semantic tags
            if prior_ver >= cur_ver:
                raise ValueError(
                    f"prior inventory version {prior_ver!r} must be older than "
                    f"current inventory version {cur_ver!r}"
                )
        except TypeError as exc:
            # In case the version objects are not directly comparable, skip
            _ = exc

    # An inventory is generally a mapping from an identifier to an element
    # or a collection of elements.  We simply check that every key in the
    # prior inventory also exists in the current inventory and that the
    # element values are unchanged except for permissible timestamp/metadata.
    ignore_attrs = {"last_modified", "created", "modified", "date_updated", "version"}
    for key, prior_elem in prior.inventory.items():
        if key not in self.inventory:
            raise KeyError(f"Key {key!r} present in prior inventory but missing in current inventory")

        cur_elem = self.inventory[key]

        # Use the element's __dict__ (or a custom attributes property) to do a light check.
        # Skip private/internal attributes and the ones in ignore_attrs.
        if hasattr(prior_elem, "__dict__"):
            prior_attrs = {
                k: v for k, v in prior_elem.__dict__.items()
                if not k.startswith("_") and k not in ignore_attrs
            }
        else:
            # Fallback: attribute lookup
            prior_attrs = None

        if prior_attrs is not None:
            for attr, prior_val in prior_attrs.items():
                cur_val = getattr(cur_elem, attr, None)
                if cur_val != prior_val:
                    raise ValueError(
                        f"Attribute {attr!r} of element with key {key!r} has changed from {prior_val!r} to {cur_val!r}"
                    )

    # If we got this far the prior inventory is a valid earlier version.
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure the argument is of the correct type
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Both inventories must expose a version attribute
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        raise AttributeError("Both inventories must have a 'version' attribute")

    # The current inventory must be newer than the prior
    if self.version <= prior.version:
        raise ValueError(
            f"Current inventory version ({self.version}) must be greater than "
            f"prior inventory version ({prior.version})"
        )

    # Retrieve the collections of items from each inventory.
    # The actual attribute name may vary; we try common candidates.
    def _get_items(obj):
        for name in ("items", "entries", "records", "data"):
            if hasattr(obj, name):
                return getattr(obj, name)
        # Fall back to __dict__ if nothing else was found
        return obj.__dict__

    prior_items = _get_items(prior)
    current_items = _get_items(self)

    # Normalize to a set of identifiers for comparison.
    def _to_id_set(collection):
        if isinstance(collection, dict):
            return set(collection.keys())
        if isinstance(collection, (list, tuple, set)):
            return {getattr(item, "id", None) for item in collection}
        # If it's a mapping-like but not dict
        try:
            return set(collection)
        except Exception:
            return set()

    prior_ids = _to_id_set(prior_items)
    current_ids = _to_id_set(current_items)

    # All items present in the prior inventory must also exist in the current one.
    missing = prior_ids - current_ids
    if missing:
        raise ValueError(
            f"The following items are present in the prior inventory but not in "
            f"the current inventory: {sorted(missing)}"
        )

    # Optionally, check that no items were removed that are not allowed to be removed
    # For now we do not enforce this rule.

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Basic identity check – the two inventories should share the same id
    try:
        self_id = self.inventory_id
    except AttributeError:
        raise AttributeError("current inventory missing 'inventory_id' attribute")
    try:
        prior_id = prior.inventory_id
    except AttributeError:
        raise AttributeError("prior inventory missing 'inventory_id' attribute")

    if self_id != prior_id:
        raise ValueError(
            f"Current inventory id ({self_id}) does not match prior inventory id ({prior_id})"
        )

    # Ensure version numbers are sensible
    self_ver = getattr(self, "version", None)
    prior_ver = getattr(prior, "version", None)
    if self_ver is None or prior_ver is None:
        raise ValueError("both inventories must expose a 'version' attribute")
    if self_ver <= prior_ver:
        raise ValueError(
            f"current version ({self_ver}) must be greater than prior version ({prior_ver})"
        )

    # Ensure that every item/key present in the prior inventory still exists
    # in the current inventory.  The inventories may expose items as a
    # sequence or mapping – we normalise to a set of keys.
    try:
        self_items = self.items
    except AttributeError:
        raise AttributeError("current inventory missing 'items' attribute")
    try:
        prior_items = prior.items
    except AttributeError:
        raise AttributeError("prior inventory missing 'items' attribute")

    if isinstance(self_items, (list, tuple, set)):
        current_keys = set(self_items)
    else:
        current_keys = set(self_items.keys())

    if isinstance(prior_items, (list, tuple, set)):
        prior_keys = set(prior_items)
    else:
        prior_keys = set(prior_items.keys())

    missing = prior_keys - current_keys
    if missing:
        raise ValueError(
            "current inventory does not contain all items that existed in the prior inventory: "
            + str(missing)
        )

    # If all checks pass, the prior inventory is considered valid
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Initialise the result dictionary
    logical_path_map = {}

    # The inventory is expected to be a mapping where keys are logical
    # paths and values are themselves mappings of version identifiers to file
    # metadata.  For example:
    #
    #   inventory = {
    #       'path/to/state': {
    #           '1': {'content_file': 'file1.xml', 'version': '1'},
    #           '2': {'content_file': 'file2.xml', 'version': '2'},
    #           ...
    #       },
    #       ...
    #   }
    #
    # If the inventory structure differs, the code attempts a best‑effort
    # extraction of the `content_file` and `version` attributes by checking
    # for a few common key names.

    # Convert the provided version to an integer or leave it as a string
    # in order to allow numeric or lexical comparison.
    try:
        target_version = int(version)
        compare_as_int = True
    except Exception:
        target_version = version
        compare_as_int = False

    for logical_path, versioned_entries in inventory.items():
        file_set = set()
        for entry_version, entry in versioned_entries.items():
            # Determine the version of this entry
            if isinstance(entry_version, str):
                try:
                    entry_ver = int(entry_version)
                except Exception:
                    entry_ver = entry_version
            else:
                entry_ver = entry_version

            # Apply comparison
            if compare_as_int:
                if entry_ver >= target_version:
                    # Extract the content file path
                    content_file = entry.get('content_file') or entry.get('file') or entry.get('path')
                    if content_file:
                        file_set.add(content_file)
            else:
                # For string comparison, allow lexicographic comparison
                if str(entry_ver) >= str(target_version):
                    content_file = entry.get('content_file') or entry.get('file') or entry.get('path')
                    if content_file:
                        file_set.add(content_file)

        if file_set:
            logical_path_map[logical_path] = file_set

    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    import collections

    path_map = collections.defaultdict(set)

    # Assume inventory is an iterable of entries where each entry
    # contains a logical_path, a version, and a content_file.
    # For example: (logical_path, version, content_file)
    for entry in inventory:
        # Allow entry to be a tuple or an object with attributes.
        if isinstance(entry, (list, tuple)):
            try:
                logical_path, entry_version, content_file = entry
            except ValueError:
                # Skip malformed entries
                continue
        else:
            try:
                logical_path = getattr(entry, "logical_path")
                entry_version = getattr(entry, "version")
                content_file = getattr(entry, "content_file")
            except AttributeError:
                continue

        # Include this file if its version matches the requested one.
        # Also include duplicates from later versions by checking if the
        # entry_version is greater than the requested version.
        if entry_version == version or entry_version > version:
            path_map[logical_path].add(content_file)

    # Convert defaultdict back to a normal dict before returning.
    return dict(path_map)

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Initialise the mapping with an empty set for each logical path
    logical_path_map = {}

    # Collect files for the requested version and all earlier versions
    for ver, mapping in inventory.items():
        if ver > version:
            # We only want files up to and including the requested version
            continue
        for logical_path, content_file in mapping.items():
            logical_path_map.setdefault(logical_path, set()).add(content_file)

    # Additionally, include any duplicate files that might appear in later
    # versions for the same logical paths
    for later_ver, later_mapping in inventory.items():
        if later_ver <= version:
            continue  # duplicates have already been collected
        for logical_path, content_file in later_mapping.items():
            if logical_path in logical_path_map:
                logical_path_map[logical_path].add(content_file)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    required = ["file", "checksum"]
    for key in required:
        if key not in fixity:
            raise ValueError(f"Missing required key '{key}' in fixity block")

    file_name = fixity["file"]
    if file_name not in manifest_files:
        raise ValueError(f"File '{file_name}' referenced in fixity block is not present in the manifest")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.
    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("fixity block must be a dictionary")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be a list, set or tuple")

    # Allowed keys in a fixity block
    allowed_keys = {"entries", "checksum", "algorithm", "files"}
    for key in fixity:
        if key not in allowed_keys:
            raise ValueError(f"Unexpected key '{key}' in fixity block")

    # The primary structure expected is a list of entries
    entries = fixity.get("entries") or fixity.get("files")
    if entries is None:
        raise ValueError("fixity block must contain 'entries' or 'files' key")
    if not isinstance(entries, list):
        raise ValueError("The 'entries' or 'files' key must map to a list")

    # Each entry should be a dict containing a file identifier and optionally other metadata
    for idx, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise ValueError(f"Entry {idx} in fixity block is not a dictionary")
        if "id" not in entry:
            raise ValueError(f"Entry {idx} missing required 'id' field")
        file_id = entry["id"]
        if file_id not in manifest_files:
            raise KeyError(f"File ID '{file_id}' in fixity block not found in manifest_files")

        # Optional check: if a checksum is provided, it should be a string
        if "checksum" in entry and not isinstance(entry["checksum"], str):
            raise ValueError(f"Checksum for entry {idx} must be a string")

        # Optional check: if an algorithm is provided, it should be a string
        if "algorithm" in entry and not isinstance(entry["algorithm"], str):
            raise ValueError(f"Algorithm for entry {idx} must be a string")

    # If all checks passed, return True to indicate successful validation
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError('Fixity block must be a dictionary')

    files = fixity.get('files')
    if files is None:
        raise ValueError('Fixity block is missing required "files" key')
    if not isinstance(files, list):
        raise ValueError('"files" must be a list')

    expected_paths = set(manifest_files)
    seen_paths = set()

    for i, entry in enumerate(files):
        if not isinstance(entry, dict):
            raise ValueError(f'File entry at index {i} is not a dictionary')
        # required keys in each file entry
        required = {'path', 'hash', 'size'}
        if not required.issubset(entry):
            missing = required - entry.keys()
            raise ValueError(f'File entry at index {i} is missing keys: {sorted(missing)}')

        path = entry['path']
        if path in seen_paths:
            raise ValueError(f'Duplicate file path in fixity block: {path}')
        seen_paths.add(path)

        if path not in expected_paths:
            raise ValueError(f'File path "{path}" referenced in fixity is not present in the manifest')

    # Ensure every manifest file has a corresponding entry in the fixity
    missing_from_fixity = expected_paths - seen_paths
    if missing_from_fixity:
        raise ValueError(f'The following manifest files are not referenced in the fixity block: {sorted(missing_from_fixity)}')

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")
    if "files" not in fixity:
        raise ValueError("fixity block must contain 'files' key")
    files = fixity["files"]
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")
    seen = set()
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each entry in 'files' must be a dictionary")
        if "file" not in entry or "hash" not in entry:
            raise ValueError("Each file entry must contain 'file' and 'hash' keys")
        file_path = entry["file"]
        if file_path not in manifest_files:
            raise ValueError(f"File '{file_path}' referenced in fixity block not present in manifest")
        if file_path in seen:
            raise ValueError(f"Duplicate file entry for '{file_path}' in fixity block")
        seen.add(file_path)

def files_list(path):
    """Return the files in `path`"""
    import os
    if not os.path.isdir(path):
        raise ValueError(f"{path} is not a directory")
    return [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))]

def files_list(path):
    """Return the files in `path`"""
    import os
    return [f for f in os.listdir(path)
            if os.path.isfile(os.path.join(path, f))]

