    # Header with class name and optional id
    if hasattr(self, 'id') and self.id is not None:
        header = f"{indent_str}{self.__class__.__name__} (id={self.id})"
    else:
        header = f"{indent_str}{self.__class__.__name__}"
    lines = [header]

    # Show attributes except internal and callables
    attrs = {k: v for k, v in self.__dict__.items()
             if not k.startswith('_') and not callable(v)}
    if attrs:
        for k, v in attrs.items():
            lines.append(f"{indent_str}  {k} = {v!r}")

    # If debugging, show the class's simple representation
    if debug:
        lines.append(f"{indent_str}  repr = {repr(self)}")

    # Recursively pretty-print child elements
    try:
        children = list(self)
    except Exception:
        children = []

    for child in children:
        # Only recurse on elements that support pretty
        if hasattr(child, 'pretty') and callable(child.pretty):
            child_str = child.pretty(indent + 1, debug=debug)
            lines.append(child_str)
