            raise RuntimeError(
                f"Command '{' '.join(cmd)}' failed with return code {process.returncode}"
                f"{' and stderr: ' + stderr if not hide_stderr else ''}"
            )
        last_output = stdout

    return last_output

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        command = [commands]
    else:
        command = list(commands)
    if args:
        if isinstance(args, (list, tuple)):
            command.extend(args)
        else:
            command.append(str(args))

    if verbose:
        print(f"Executing command: {' '.join(command)}")
        if cwd:
            print(f"Working directory: {cwd}")

    # Prepare environment
    process_env = os.environ.copy()
    if env:
        process_env.update(env)

    # Run the command
    result = subprocess.run(
        command,
        cwd=cwd,
        env=process_env,
        capture_output=True,
        text=True,
        check=False
    )

    # Handle hidden stderr
    if hide_stderr:
        stderr_output = ''
    else:
        stderr_output = result.stderr

    if verbose:
        if result.stdout:
            print("STDOUT:")
            print(result.stdout)
        if stderr_output:
            print("STDERR:")
            print(stderr_output)
        print(f"Return code: {result.returncode}")

    return result.stdout, result.returncode, stderr_output

