def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Assume the object hierarchy can be traversed via an iterable,
    # e.g. the root provides an `iter_objects()` method.
    try:
        objects_iter = self.iter_objects()
    except AttributeError:
        # Fallback: iterate over children if no dedicated iterator
        objects_iter = iter(self)

    for obj in objects_iter:
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                # The object itself should provide a validate method
                if hasattr(obj, "validate"):
                    obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Validation failed for object '{getattr(obj, 'id', repr(obj))}': {exc}")

        if check_digests and is_valid:
            try:
                # If the object provides a digest verification method
                if hasattr(obj, "verify_digest"):
                    obj.verify_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Digest check failed for object '{getattr(obj, 'id', repr(obj))}': {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _traverse(node):
        nonlocal num_objects, good_objects
        num_objects += 1
        valid = True

        # Validate the object if requested
        if validate_objects:
            try:
                if hasattr(node, 'validate'):
                    node.validate()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f'Validation error for {node}: {e}')

        # Check the object digest if requested
        if check_digests:
            try:
                if hasattr(node, 'verify_digest'):
                    node.verify_digest()
                elif hasattr(node, 'check_digest'):
                    node.check_digest()
            except Exception as e:
                valid = False
                if show_warnings:
                    print(f'Digest check error for {node}: {e}')

        if valid:
            good_objects += 1

        # Recurse over children if any
        children = None
        if hasattr(node, 'children'):
            children = node.children
        elif hasattr(node, '__iter__'):
            try:
                children = list(node)
            except Exception:
                children = None
        if children:
            for child in children:
                # Skip any items that cannot be traversed
                try:
                    _traverse(child)
                except Exception:
                    if show_warnings:
                        print(f'Could not traverse child {child} of {node}')

    _traverse(self)
    return num_objects, good_objects

