    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    from collections import OrderedDict
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge_node_values(v1, v2):
        """Recursively merge two ruamel.yaml nodes."""
        # If both are mapping nodes: merge by key
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            # Build a mapping of key value to index in list
            merged_items = []
            key_index = {}
            for idx, (k, val) in enumerate(v1.value):
                merged_items.append([k, val])
                key_index[k.value] = idx

            # Process second mapping
            for k2, val2 in v2.value:
                if k2.value in key_index:
                    idx = key_index[k2.value]
                    merged_items[idx][1] = merge_node_values(merged_items[idx][1], val2)
                else:
                    merged_items.append([k2, val2])

            # Convert back to tuple list and create new MappingNode
            return MappingNode(tag='tag:yaml.org,2002:map',
                               value=[tuple(item) for item in merged_items])

        # For non-mapping node conflict, the last one wins
        return v2

    # Preserve order of first occurrence
    merged_dict = OrderedDict()
    for key_node, val_node in nodes:
        # Duplicate key found
        if key_node.value in merged_dict:
            existing_key, existing_val = merged_dict[key_node.value]
            merged_val = merge_node_values(existing_val, val_node)
            merged_dict[key_node.value] = (existing_key, merged_val)
        else:
            merged_dict[key_node.value] = (key_node, val_node)

    return list(merged_dict.values())

