def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url

    import re

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    # Replace {key} placeholders
    url = re.sub(r'\{([^{}]+)\}', _repl, url)
    # Replace %(key)s placeholders
    url = re.sub(r'%\(([^)]+)\)s', _repl, url)

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    import re
    pattern = re.compile(r'\{([^}]+)\}|\%\(([^)]+)\)s')
    def _replace(match):
        key = match.group(1) or match.group(2)
        return str(url_args.get(key, match.group(0)))
    return pattern.sub(_replace, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args

    Parameters:
        url (str): The URL containing placeholders.
        url_args (dict): A mapping from placeholder names to replacement values.

    Returns:
        str: The URL with placeholders replaced by their corresponding values.
    """
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    # Replace placeholders in the form <key> or {key}
    for key, value in url_args.items():
        placeholder_lt_gt = f"<{key}>"
        placeholder_brace = f"{{{key}}}"
        if placeholder_lt_gt in url:
            url = url.replace(placeholder_lt_gt, str(value))
        if placeholder_brace in url:
            url = url.replace(placeholder_brace, str(value))

    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    class _SafeDict(dict):
        def __missing__(self, key):
            return '{' + key + '}'
    return url.format_map(_SafeDict(url_args))

