def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("negative numbers are not supported")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters")
    # Handle zero explicitly
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        while number > 0:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))
    # Apply optional padding
    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non-negative")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("int_to_string only supports non-negative integers")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two symbols")

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while number > 0:
            digits.append(alphabet[number % base])
            number //= base
        digits.reverse()

    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non-negative")
        pad_len = padding - len(digits)
        if pad_len > 0:
            digits = [alphabet[0]] * pad_len + digits

    return "".join(digits)

