def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Determine which platform to use
    if platform == 'this':
        # Default to POSIX for this implementation
        platform = 1

    # POSIX shell-like splitting
    if platform == 1:
        pattern = r'''(?:"([^"]*)"|'([^']*)'|(\S+))'''
        args = []
        for m in re.finditer(pattern, s):
            # Use the first non-None group
            args.append(m.group(1) or m.group(2) or m.group(3))
        return args

    # Windows CMD-like splitting
    args = []
    i = 0
    n = len(s)
    while i < n:
        # Skip leading whitespace
        while i < n and s[i].isspace():
            i += 1
        if i >= n:
            break

        arg = ''
        quote = None

        # Detect opening quote
        if s[i] in ('"', "'"):
            quote = s[i]
            i += 1

        while i < n:
            c = s[i]
            if quote:
                if c == quote:
                    i += 1
                    break
                elif c == '\\':
                    if i + 1 < n and s[i + 1] == quote:
                        arg += quote
                        i += 2
                    else:
                        arg += c
                        i += 1
                else:
                    arg += c
                    i += 1
            else:
                if c.isspace():
                    break
                elif c == '\\':
                    if i + 1 < n:
                        arg += s[i + 1]
                        i += 2
                    else:
                        i += 1
                elif c in ('"', "'"):
                    quote = c
                    i += 1
                else:
                    arg += c
                    i += 1

        args.append(arg)

    return args

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)"""
    import re
    # Determine POSIX or Windows style
    if platform == 'this':
        posix = True
    elif platform == 1:
        posix = True
    elif platform == 0:
        posix = False
    else:
        posix = True

    # Regular expression to capture quoted and unquoted tokens
    if posix:
        pattern = r'''(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|([^ \t\n\r\f\v]+))'''
    else:
        pattern = r'''(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|([^ \t\n\r\f\v]+))'''

    token_re = re.compile(pattern, re.VERBOSE)
    tokens = []
    for m in token_re.finditer(s):
        dbl, sgl, raw = m.groups()
        if dbl is not None:
            token = re.sub(r'\\(.)', r'\1', dbl)
        elif sgl is not None:
            token = re.sub(r'\\(.)', r'\1', sgl)
        else:
            token = raw
        tokens.append(token)
    return tokens

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ["git", "ls-files", "--others", "--ignored", "--exclude-standard"],
            text=True,
            stderr=subprocess.STDOUT,
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        # If git is not available or the command fails, return an empty string
        return ""
    # Split output into lines, remove empty lines, sort, and join with commas
    files = [line.strip() for line in output.splitlines() if line.strip()]
    files.sort()
    return ",".join(files)

