def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick check for common localhost identifiers
    if host in ('localhost', '127.0.0.1', '::1'):
        return True

    try:
        # Resolve the host to all possible addresses
        addr_infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Unable to resolve the host name
        return False

    for family, _, _, _, sockaddr in addr_infos:
        if family == socket.AF_INET:
            # IPv4: any address in 127.0.0.0/8 is loopback
            if sockaddr[0].startswith('127.'):
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback is ::1
            if sockaddr[0] == '::1':
                return True

    # No loopback address found
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host_str = str(host).strip()
    if host_str.lower() == "localhost":
        return True
    try:
        # Resolve hostname to an IP address
        ip = socket.gethostbyname(host_str)
        # Check for IPv4 loopback
        if ip.startswith("127."):
            return True
        # Handle IPv6 loopback
        if ip == "::1":
            return True
    except socket.error:
        # If resolution fails, try to check if the string itself is an IP
        try:
            import ipaddress
            return ipaddress.ip_address(host_str).is_loopback
        except (ValueError, ImportError):
            return False
    return False

