    if os.name != 'nt':
        return False
    ostype = os.getenv('OSTYPE', '').lower()
    return ostype.startswith('msys') or ostype.startswith('cygwin') or ostype.startswith('mingw')

def is_gitbash():
    """Return True if running inside Windows Git Bash."""
    import os
    # Git Bash (or Msys) sets OSTYPE to a string containing 'cygwin' or 'msys'.
    # os.name will still be 'nt' on Windows.
    if os.name != 'nt':
        return False
    ostype = os.environ.get('OSTYPE', '').lower()
    return bool(ostype and ('cygwin' in ostype or 'msys' in ostype))

