    return os.getenv('OSTYPE', '').lower().startswith('msys')

def _resolve_string(matcher):
    '''Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.'''
    if ':' in matcher:
        name, default = matcher.split(':', 1)
        name = name.strip()
        default = default.strip()
    else:
        name = matcher.strip()
        default = None
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise RuntimeError(f"Environment variable '{name}' is not defined and no default value provided.")
    return value

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Attempt to extract the variable name from the matcher.
    name = None
    default = None

    # If matcher behaves like a regex Match object, use group(1) for the variable name.
    if hasattr(matcher, 'group'):
        try:
            name = matcher.group(1)
        except Exception:
            raise ValueError("Unable to extract variable name from matcher.")
        # Group 2 often contains a default value if present.
        try:
            default = matcher.group(2)
        except Exception:
            pass
    # Fallback: if matcher is a tuple/list-like, assume first element is name, second is default.
    elif isinstance(matcher, (list, tuple)):
        if len(matcher) >= 1:
            name = matcher[0]
        if len(matcher) >= 2:
            default = matcher[1]
    else:
        raise ValueError("Matcher must provide variable name via group() or index.")

    if name is None:
        raise ValueError("Variable name could not be determined from matcher.")

    # Resolve environment variable
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' not found and no default value provided.")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    parsed = urllib.parse.urlparse(image_href)
    # If we have a scheme and netloc, treat as URL
    if parsed.scheme and parsed.netloc:
        if parsed.scheme not in ('http', 'https'):
            raise ValueError(f"Unsupported scheme '{parsed.scheme}' in image href '{image_href}'")
        use_ssl = parsed.scheme == 'https'
        netloc = parsed.netloc
        path = parsed.path
        if path.endswith('/'):
            raise ValueError(f"Image href '{image_href}' does not point to a specific image")
        image_id = path.split('/')[-1]
        if not image_id:
            raise ValueError(f"Could not determine image id from href '{image_href}'")
        return (image_id, netloc, use_ssl)
    # No scheme/netloc: maybe a local or relative path
    if not parsed.scheme and not parsed.netloc:
        image_id = image_href.split('/')[-1]
        if not image_id:
            raise ValueError(f"Invalid image href '{image_href}' - cannot extract image id")
        return (image_id, '', False)
    raise ValueError(f"Image href '{image_href}' is malformed")

