import os
import shlex

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    def _run_single(cmd, cmd_args):
        env_dict = os.environ.copy()
        if env:
            env_dict.update(env)

        # Build command list
        if isinstance(cmd, (list, tuple)):
            cmd_list = list(cmd)
        else:
            cmd_list = shlex.split(str(cmd))

        # Add arguments
        if cmd_args:
            if isinstance(cmd_args, (list, tuple)):
                cmd_list.extend(cmd_args)
            else:
                cmd_list.append(str(cmd_args))

        if verbose:
            print("Running command:", ' '.join(shlex.quote(part) for part in cmd_list))

        try:
            result = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env_dict,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=False
            )
        except Exception as exc:
            if verbose:
                print("Error executing command:", exc)
            raise

        if verbose and not hide_stderr:
            print("stdout:\n", result.stdout)
            print("stderr:\n", result.stderr)

        return result

    # If multiple commands are provided, run them sequentially
    if isinstance(commands, (list, tuple)) and not isinstance(commands, str):
        results = []
        for cmd in commands:
            results.append(_run_single(cmd, args))
        return results
    else:
        return _run_single(commands, args)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Flatten the command and arguments into a list of strings
    if isinstance(commands, (str, bytes)):
        cmd_list = [commands]
    else:
        cmd_list = [str(c) for c in commands]
    if isinstance(args, (str, bytes)):
        args_list = [args]
    else:
        args_list = [str(a) for a in args]
    full_cmd = cmd_list + args_list

    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Decide how to handle stderr
    stderr_setting = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_setting,
            check=True,
            text=True,
        )
    except subprocess.CalledProcessError as e:
        # If hide_stderr is True, don't print the stderr
        if not hide_stderr and e.stderr:
            print(e.stderr, file=sys.stderr)
        raise

    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
