    # Determine whether we're on Python 2 or 3
    try:
        on_py2 = (type(u"") is unicode)  # py2 unicode type exists
    except NameError:
        on_py2 = False

    # Prepare dump arguments
    dump_kwargs = {"allow_unicode": True, "default_flow_style": False}

    if dumper is not None:
        yaml_string = yaml.dump(obj, Dumper=dumper, **dump_kwargs)
