def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''

    import os
    import json

    # Ensure we have a sequence of filenames
    if isinstance(config_filenames, (str, bytes)):
        config_filenames = [config_filenames]
    elif not isinstance(config_filenames, (list, tuple, set)):
        config_filenames = list(config_filenames)

    parsed = {}
    errors = []

    def _make_record(exc):
        """Create a LogRecord for an exception."""
        return logging.LogRecord(
            name=__name__,
            level=logging.ERROR,
            pathname=__file__,
            lineno=0,
            msg=str(exc),
            args=(),
            exc_info=exc
        )

    def _resolve_env(obj):
        """Recursively replace environment variables in strings."""
        if isinstance(obj, dict):
            return {k: _resolve_env(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env(v) for v in obj]
        if isinstance(obj, str):
            # Use os.path.expandvars to replace $VAR or ${VAR}
            return os.path.expandvars(obj)
        return obj

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                # Attempt to load as JSON
                cfg = json.load(f)
        except Exception as e:
            errors.append(_make_record(f"Failed to load {fname}: {e}"))
            continue

        # Verify config is a dictionary
        if not isinstance(cfg, dict):
            errors.append(_make_record(f"Configuration in {fname} is not a dictionary"))
            continue

        # Apply overrides if provided
        if overrides:
            # shallow update; nested merges are not performed
            cfg.update(overrides)

        # Resolve environment variables if requested
        if resolve_env:
            try:
                cfg = _resolve_env(cfg)
            except Exception as e:
                errors.append(_make_record(f"Error resolving environment variables in {fname}: {e}"))
                continue

        parsed[fname] = cfg

    return parsed, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import os
    import logging

    logger = logging.getLogger(__name__)
    configs = {}
    log_records = []

    def resolve_env_vars(obj):
        if isinstance(obj, dict):
            return {k: resolve_env_vars(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [resolve_env_vars(v) for v in obj]
        elif isinstance(obj, str):
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, obj)
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except Exception as e:
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                fn=__file__,
                lno=0,
                msg='Error parsing %s: %s',
                args=(filename, e),
                exc_info=e
            )
            log_records.append(record)
            continue

        if not isinstance(data, dict):
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                fn=__file__,
                lno=0,
                msg='Configuration %s is not a dict',
                args=(filename,),
                exc_info=None
            )
            log_records.append(record)
            continue

        if overrides:
            data.update(overrides)

        if resolve_env:
            data = resolve_env_vars(data)

        configs[filename] = data

    return (configs, log_records)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    result = {}
    errors = []
    logger = logging.getLogger(__name__)
    for fn in config_filenames:
        try:
            if fn.lower().endswith('.json'):
                import json
                with open(fn, 'r', encoding='utf-8') as f:
                    cfg = json.load(f)
            elif fn.lower().endswith(('.ini', '.cfg', '.cnf')):
                import configparser
                parser = configparser.ConfigParser()
                with open(fn, 'r', encoding='utf-8') as f:
                    parser.read_file(f)
                cfg = {section: dict(parser.items(section)) for section in parser.sections()}
            else:
                # fallback to ini parser
                import configparser
                parser = configparser.ConfigParser()
                with open(fn, 'r', encoding='utf-8') as f:
                    parser.read_file(f)
                cfg = {section: dict(parser.items(section)) for section in parser.sections()}
        except Exception as e:
            record = logger.makeRecord(
                name='load_configurations',
                level=logging.ERROR,
                fn=fn,
                lno=0,
                msg='Error parsing configuration file {}: {}'.format(fn, e),
                args=(),
                exc_info=None
            )
            errors.append(record)
            continue

        if overrides and isinstance(overrides, dict):
            # Merge top-level keys only
            for key, value in overrides.items():
                if key in cfg:
                    cfg[key] = value

        if resolve_env:
            import os
            def resolve(item):
                if isinstance(item, dict):
                    return {k: resolve(v) for k, v in item.items()}
                elif isinstance(item, list):
                    return [resolve(v) for v in item]
                elif isinstance(item, str):
                    return os.path.expandvars(item)
                else:
                    return item
            cfg = resolve(cfg)

        result[fn] = cfg

    return result, errors

