@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = getattr(cls, "_PROTOCOL_HANDLERS", {})
    if protocol_version is None:
        return dict(handlers)
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    handlers = getattr(cls, "_available_handlers", {})
    if protocol_version is None:
        return dict(handlers)
    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    bookmarks = cls()
    for v in values:
        if not v:
            continue
        try:
            if isinstance(v, str):
                # attempt simple CSV parsing: "label,url"
                if ',' in v:
                    label, url = [x.strip() for x in v.split(',', 1)]
                else:
                    label, url = None, v.strip()
                bookmark = Bookmark(label=label, target=url)
            else:
                bookmark = Bookmark(v)
            bookmarks.add(bookmark)
        except Exception:
            # silently skip malformed entries
            continue
    return bookmarks

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence

    # Treat strings, bytes, and bytearrays as their own sequences
    if isinstance(seq, (str, bytes, bytearray)):
        return seq, type(seq)

    # If seq is already a sequence (like list, tuple, set, etc.), use it directly
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # For non-sequence iterables, materialise into a list
    try:
        seq = list(seq)
    except TypeError:
        # Fallback: return as is if it can't be converted to a list
        pass

    return seq, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a concrete sequence type (list, tuple, set, frozenset), just return it
    if isinstance(seq, (list, tuple, set, frozenset)):
        return seq, type(seq)

    # If seq is an iterable that is not a string or bytes, materialise it into a list
    # (use bufsize if provided to limit how many items to materialise)
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes, bytearray)):
        if bufsize is None:
            collected = list(seq)
        else:
            import itertools
            collected = list(itertools.islice(seq, bufsize))
        return collected, type(collected)

    # For strings, bytes or bytearray, return as is, along with their types
    return seq, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Helper to detect a sequence (but not a string/bytes)
    from collections.abc import Sequence
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # If it is not a sequence, treat it as an iterator
    it = iter(seq)
    if bufsize is None:
        seq = list(it)
    else:
        from itertools import islice
        seq = list(islice(it, bufsize))

    return seq, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Determine if seq is already a sequence
    # Bytes, bytearray and memoryview are considered efficient sequence types
    if isinstance(seq, (bytes, bytearray, memoryview)):
        return seq, type(seq)

    # If seq implements the Sequence protocol, return it directly
    try:
        from collections.abc import Sequence
    except Exception:  # pragma: no cover
        Sequence = (list, tuple, tuple)

    if isinstance(seq, Sequence):
        return seq, type(seq)

    # Fallback: convert to a list
    seq = list(seq)
    return seq, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already an appropriate sequence type, keep it
    if isinstance(seq, (str, bytes, bytearray, list, tuple, set, frozenset)):
        sequence = seq
    else:
        # Try to materialise the input as a list if it is iterable
        try:
            sequence = list(seq)
        except Exception:
            # If it is not iterable, put it into a single‑item list
            sequence = [seq]

    # Apply buffering if requested
    if bufsize is not None:
        try:
            sequence = sequence[:bufsize]
        except Exception:
            # sequence might not support slicing; ignore the request
            pass

    return sequence, type(sequence)

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """

        # Return current scale
        if other is None:
            if recompute or not hasattr(self, "_scale"):
                # Determine the underlying data of the histogram.
                # The histogram may be a list, tuple, array, or a more
                # specialized object exposing its values via .values()
                # or a .data attribute.  We try these in order.
                try:
                    values = list(self)
                except TypeError:
                    try:
                        values = self.values()
                    except AttributeError:
                        try:
                            values = self.data
                        except AttributeError:
                            raise RuntimeError("Unrecognized histogram data structure")

                self._scale = float(sum(values))
            return self._scale

        # Rescale: other must be a float (or convertible)
        new_total = float(other)
        current = self.scale(recompute=True)

        if current == 0:
            raise ValueError("Cannot rescale histogram with zero scale")

        factor = new_total / current

        # Apply factor to each bin.
        # The ordering and mutability of the histogram representation
        # may vary; we attempt a few common patterns.
        try:
            # Direct list/array style
            for i in range(len(self)):
                self[i] *= factor
        except (AttributeError, TypeError):
            try:
                # If histogram is stored in a list attribute named `hist`
                hist = self.hist
                for i in range(len(hist)):
                    hist[i] *= factor
                self.hist = hist
            except Exception:
                try:
                    # Try a mapping of bin->count
                    for key in self:
                        self[key] *= factor
                except Exception:
                    raise RuntimeError("Unsupported histogram structure for rescaling")

        self._scale = new_total
        return self

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Helper: compute current scale if needed
        if other is None:
            # Compute or return stored scale
            if getattr(self, "_scale", None) is None or recompute:
                # Assume the histogram stores bin counts in self.values
                try:
                    self._scale = sum(self.values)
                except AttributeError:
                    raise AttributeError("Histogram object has no 'values' attribute to compute integral.")
            return self._scale

        # Rescale (other is numeric)
        else:
            # Ensure other is a number
            try:
                target = float(other)
            except (TypeError, ValueError):
                raise TypeError("scale() argument 'other' must be a number or None")

            # Determine current scale
            current_scale = getattr(self, "_scale", None)
            if current_scale is None or recompute:
                try:
                    current_scale = sum(self.values)
                except AttributeError:
                    raise AttributeError("Histogram object has no 'values' attribute to compute integral.")
                self._scale = current_scale

            if current_scale == 0:
                # No rescaling allowed for zero scale
                raise LenaValueError("Cannot rescale histogram with zero scale.")

            factor = target / current_scale
            # Apply factor to each bin
            # We assume the histogram uses a list or similar iterable for values
            try:
                for idx, val in enumerate(self.values):
                    self.values[idx] = val * factor
            except TypeError:
                # If self.values is a numpy array, use vectorized operation
                try:
                    self.values *= factor
                except Exception:
                    raise TypeError("Histogram 'values' attribute is not a sequence or array")

            # Store new scale
            self._scale = target
            # No return value needed

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute scale from data
    def _compute_scale():
        # try common container names for histogram bin values
        if hasattr(self, 'values'):
            return sum(self.values)
        if hasattr(self, 'data'):
            return sum(self.data)
        if hasattr(self, 'bins'):
            return sum(self.bins)
        raise AttributeError("Histogram object has no recognizable container for values")

    # Getter / recompute path
    if other is None:
        if getattr(self, '_scale', None) is None or recompute:
            self._scale = _compute_scale()
        return self._scale

    # Setter / rescaling path
    new_scale = float(other)
    # Get current accurate scale
    curr_scale = self.scale(recompute=True)
    if curr_scale == 0:
        raise LenaValueError("Histogram has zero scale and cannot be rescaled.")
    factor = new_scale / curr_scale
    # Apply scaling factor to the underlying values
    if hasattr(self, 'values'):
        for i in range(len(self.values)):
            self.values[i] *= factor
    elif hasattr(self, 'data'):
        for i in range(len(self.data)):
            self.data[i] *= factor
    elif hasattr(self, 'bins'):
        for i in range(len(self.bins)):
            self.bins[i] *= factor
    else:
        raise AttributeError("Histogram object has no recognizable container for values")
    # Update stored scale
    self._scale = new_scale
    return self

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale when no new scale is supplied
    if other is None:
        return getattr(self, "scale", None)

    # Validate that the new scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be numeric.")

    # Fetch the current scale; raise if it is undefined or zero
    current_scale = getattr(self, "scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError(
            "Cannot rescale graph with undefined or zero current scale."
        )

    # Compute scaling factor
    factor = other / current_scale

    # Identify the index of the last coordinate field
    if not hasattr(self, "fields") or not self.fields:
        raise AttributeError("Graph must have a 'fields' attribute with coordinate names.")
    last_field_index = len(self.fields) - 1

    # Apply scaling to the data
    if hasattr(self, "data"):
        for row in self.data:
            if isinstance(row, (list, tuple)):
                # Extend row if shorter than expected
                if len(row) <= last_field_index:
                    raise IndexError("Row does not contain enough fields to scale.")
                row[last_field_index] = row[last_field_index] * factor
            else:
                # If row is a dict, use field name
                key = self.fields[last_field_index]
                if key in row:
                    row[key] = row[key] * factor
                else:
                    raise KeyError(f"Missing expected field '{key}' in row.")

    # Apply scaling to associated error values if present
    if hasattr(self, "errors"):
        for err in self.errors:
            if isinstance(err, (list, tuple)):
                if len(err) <= last_field_index:
                    raise IndexError("Error row does not contain enough fields to scale.")
                err[last_field_index] = err[last_field_index] * factor
            else:
                key = self.fields[last_field_index]
                if key in err:
                    err[key] = err[key] * factor
                else:
                    raise KeyError(f"Missing expected error field '{key}' in error entry.")

    # Finally, update the graph's scale value
    self.scale = other
    return other

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Determine how to iterate over the histogram bins
    # First try an attribute that contains bin objects
    if hasattr(hist, "bins") and hasattr(hist, "contents") is False:
        bin_iter = hist.bins
    elif hasattr(hist, "edges") and hasattr(hist, "contents"):
        # typical numpy histogram representation
        edges = hist.edges
        contents = hist.contents
        bin_iter = list(zip(edges[:-1], edges[1:], contents))
    elif hasattr(hist, "__iter__"):
        # fallback: direct iterable of bin contents
        try:
            bin_iter = list(hist)
        except TypeError:
            raise ValueError("Unable to interpret histogram: no suitable bins or edges.")
    else:
        raise ValueError("Unable to interpret histogram: no suitable bins or edges.")

    points = []

    # Helper to compute coordinate from a bin object or edges
    def _coord_from_bin(bin_obj, edges, index):
        if get_coordinate == "left":
            return edges[index]
        elif get_coordinate == "right":
            return edges[index + 1]
        elif get_coordinate == "middle":
            return 0.5 * (edges[index] + edges[index + 1])
        else:
            raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    # Iterate over bins
    if hasattr(bin_iter[0] if bin_iter else None, "__iter__") and not isinstance(bin_iter[0], (int, float)):
        # bin_iter yielded a tuple like (xlow, xhigh, content)
        for idx, (xlow, xhigh, bin_content) in enumerate(bin_iter):
            # Determine coordinate
            if get_coordinate == "left":
                coord = xlow
            elif get_coordinate == "right":
                coord = xhigh
            elif get_coordinate == "middle":
                coord = 0.5 * (xlow + xhigh)
            else:
                raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
            # Determine value
            if make_value is None:
                value = bin_content
            else:
                value = make_value(bin_content)
            # Build point
            if isinstance(value, (list, tuple, set)):
                point = (coord,) + tuple(value)
            else:
                point = (coord, value)
            points.append(point)
    else:
        # bin_iter yielded bin objects or simple content
        # Try to handle both cases
        for idx, bin_obj in enumerate(bin_iter):
            # Determine coordinate
            coord = None
            if hasattr(bin_obj, "xmin") and hasattr(bin_obj, "xmax"):
                if get_coordinate == "left":
                    coord = bin_obj.xmin
                elif get_coordinate == "right":
                    coord = bin_obj.xmax
                elif get_coordinate == "middle":
                    coord = 0.5 * (bin_obj.xmin + bin_obj.xmax)
            elif hasattr(bin_obj, "xlow") and hasattr(bin_obj, "xhigh"):
                if get_coordinate == "left":
                    coord = bin_obj.xlow
                elif get_coordinate == "right":
                    coord = bin_obj.xhigh
                elif get_coordinate == "middle":
                    coord = 0.5 * (bin_obj.xlow + bin_obj.xhigh)
            elif hasattr(bin_obj, "edges") and len(bin_obj.edges) == 2:
                if get_coordinate == "left":
                    coord = bin_obj.edges[0]
                elif get_coordinate == "right":
                    coord = bin_obj.edges[1]
                elif get_coordinate == "middle":
                    coord = 0.5 * (bin_obj.edges[0] + bin_obj.edges[1])
            else:
                # Fallback: if histogram provided edges separately
                if hasattr(hist, "edges"):
                    edges = hist.edges
                    coord = _coord_from_bin(bin_obj, edges, idx)
            if coord is None:
                raise ValueError(f"Cannot determine coordinate for bin at index {idx}")
            # Determine value
            if make_value is None:
                if hasattr(bin_obj, "content"):
                    value = bin_obj.content
                else:
                    value = bin_obj
            else:
                if hasattr(bin_obj, "content"):
                    value = make_value(bin_obj.content)
                else:
                    value = make_value(bin_obj)
            # Build point
            if isinstance(value, (list, tuple, set)):
                point = (coord,) + tuple(value)
            else:
                point = (coord, value)
            points.append(point)

    # Determine graph scale
    if scale is True:
        scale = getattr(hist, "scale", None)
    elif scale is None:
        scale = getattr(hist, "scale", None)

    # Instantiate graph
    graph = Graph(field_names=field_names, scale=scale)
    for pt in points:
        graph.add_point(*pt)
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # 1. Check interface claim
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"'{candidate.__name__ if hasattr(candidate, '__name__') else str(candidate)}' does not "
                    f"declare providing interface '{iface.__name__}'"
                )
        except Exception as exc:
            errors.append(
                f"Error checking providedBy for '{candidate.__name__ if hasattr(candidate, '__name__') else str(candidate)}': {exc}"
            )

    # Helper function to compare signatures
    def _signature_mismatch(name, iface_sig, cand_sig):
        # Simplistic comparison: argument count and names (ignoring varargs/kws)
        iface_args = iface_sig.args
        cand_args = cand_sig.args

        # Remove 'self' or 'cls' from candidate args if present
        if cand_args and cand_args[0] in ("self", "cls"):
            cand_args = cand_args[1:]

        if len(iface_args) != len(cand_args):
            return (
                f"method '{name}' argument count mismatch: expected "
                f"{len(iface_args)} but got {len(cand_args)}"
            )

        if iface_args != cand_args:
            return (
                f"method '{name}' argument name mismatch: expected "
                f"{iface_args} but got {cand_args}"
            )
        return None

    # 2. Check required methods
    for name, iface_attr in getattr(iface, "methods", {}).items():
        if not hasattr(candidate, name):
            errors.append(f"Missing method '{name}'")
            continue

        candidate_method = getattr(candidate, name)

        try:
            cand_sig = inspect.signature(candidate_method)
        except Exception as exc:
            errors.append(f"Could not inspect signature of method '{name}': {exc}")
            continue

        # try to obtain interface method signature
        iface_sig = None
        try:
            # Interface method objects hold the original function object in .0
            # If they are simple functions, fetch directly
            iface_func = iface_attr
            iface_sig = inspect.signature(iface_func)
        except Exception:
            # If we can't get signature, skip further checks
            pass

        if iface_sig:
            mismatch = _signature_mismatch(name, iface_sig, cand_sig)
            if mismatch:
                errors.append(mismatch)

    # 3. Check required attributes
    for name in getattr(iface, "attributes", {}):
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute '{name}'")
            continue
        if vtype is not None:
            val = getattr(candidate, name)
            if not isinstance(val, vtype):
                errors.append(
                    f"attribute '{name}' has type {type(val).__name__}, "
                    f"expected {vtype.__name__}"
                )

    # 4. Raise or return
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("Multiple interface verification errors: " + "; ".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*.

    Returns a true value if everything that could be checked passed.
    Raises zope.interface.Invalid if any required condition fails.
    """
    from zope.interface import Invalid
    import inspect

    errors = []

    # Check interface provision
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate {candidate!r} does not provide interface {iface.__name__}")
        except Exception as exc:
            errors.append(f"Error checking providedBy: {exc}")

    # Check methods
    for method_name in iface.names():
        # Skip attributes; will handle below
        if method_name in iface.attributes:
            continue
        if not hasattr(candidate, method_name):
            errors.append(f"Missing method '{method_name}'")
            continue
        method = getattr(candidate, method_name)
        if not callable(method):
            errors.append(f"Attribute '{method_name}' is not callable")
            continue

        # Compare signatures if possible
        try:
            iface_method = getattr(iface, method_name)
            iface_sig = inspect.signature(iface_method)
            cand_sig = inspect.signature(method)
            # Simplistic check: number of positional-only+positional-or-keyword args
            iface_params = [p for p in iface_sig.parameters.values()
                            if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD, p.VAR_KEYWORD, p.VAR_POSITIONAL)]
            cand_params = [p for p in cand_sig.parameters.values()
                           if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD, p.VAR_KEYWORD, p.VAR_POSITIONAL)]
            if len(cand_params) < len(iface_params):
                errors.append(f"Method '{method_name}' has too few parameters (expected at least {len(iface_params)}, got {len(cand_params)})")
        except Exception:
            # If signature extraction fails, skip
            pass

    # Check attributes
    for attr_name in iface.attributes:
        if not hasattr(candidate, attr_name):
            errors.append(f"Missing attribute '{attr_name}'")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    # Determine the class of the candidate (handle class objects and instances)
    candidate_class = candidate if isinstance(candidate, type) else type(candidate)

    # Iterate over attributes defined in the interface
    for name, attr in iface.__dict__.items():
        if name.startswith('_'):  # Skip private/internal attributes
            continue
        if callable(attr):
            # For methods, the candidate must provide a callable with the same name
            if not hasattr(candidate_class, name) or not callable(getattr(candidate_class, name)):
                if not tentative:
                    raise AttributeError(
                        f"Candidate does not implement required method '{name}' from interface '{iface.__name__}'")
                return False
        else:
            # For non-callable attributes, the candidate must have a compatible value
            if not hasattr(candidate_class, name):
                if not tentative:
                    raise AttributeError(
                        f"Candidate does not provide required attribute '{name}' from interface '{iface.__name__}'")
                return False

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Basic type checks
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a type, got {type(iface).__name__}")
    if not isinstance(candidate, type):
        raise TypeError(f"candidate must be a type, got {type(candidate).__name__}")

    # Direct subclass relationship is the simplest guarantee
    if issubclass(candidate, iface):
        return True

    # If not a subclass, perform a minimal duck‑typing check
    missing = []
    for attr in dir(iface):
        # ignore private/internal attributes and special methods
        if attr.startswith('_'):
            continue
        if not hasattr(candidate, attr):
            missing.append(attr)

    if missing:
        if tentative:
            return False
        raise ValueError(
            f"Candidate {candidate.__name__} does not implement required attributes "
            f"of interface {iface.__name__}: {', '.join(missing)}"
        )

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    This helper attempts to determine whether *candidate* satisfies the
    requirements of *iface*.  *iface* is expected to be a class (or an
    ``abc.ABCMeta`` interface).  *candidate* can be either a class (for
    subclass checks) or an instance (for ``isinstance`` checks).  If the
    basic ``issubclass``/``isinstance`` test fails, the function falls
    back to a lightweight attribute‑based check: all attributes (except
    dunder methods) defined on *iface* must be present on *candidate*.
    If *tentative* is ``True``, the function will return ``False`` on
    any failure but will **not** raise an exception.  If *tentative* is
    ``False`` an exception will be raised when the check fails.

    Returns:
        bool: ``True`` if *candidate* satisfies *iface*, otherwise
              ``False`` (or an exception if *tentative* is ``False``).
    """
    if candidate is None:
        return False

    try:
        # 1. try the normal isinstance / issubclass route
        if isinstance(iface, type):
            # candidate might be a class
            if isinstance(candidate, type):
                if issubclass(candidate, iface):
                    return True
            else:
                if isinstance(candidate, iface):
                    return True

        # 2. fall back to attribute‑based checking for a more general interface
        #    only non‑dunder attributes are considered
        iface_attrs = set(attr for attr in dir(iface)
                           if not (attr.startswith('__') and attr.endswith('__')))
        for attr_name in iface_attrs:
            if not hasattr(candidate, attr_name):
                raise AttributeError(f"Missing attribute {attr_name!r}")
            iface_val = getattr(iface, attr_name, None)
            cand_val = getattr(candidate, attr_name)
            # If the attribute on iface is callable and abstract, we only check
            # that the candidate has a callable of the same name.
            if callable(iface_val) or getattr(iface_val, "__isabstractmethod__", False):
                if not callable(cand_val):
                    raise TypeError(f"Attribute {attr_name!r} is not callable")
        # All checks passed
        return True

    except Exception as exc:
        if tentative:
            return False
        else:
            raise ValueError(f"Candidate does not satisfy the interface {iface!r}") from exc

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # If candidate is a class/type, check subclass relationship
    if isinstance(candidate, type):
        if issubclass(candidate, iface):
            return True
        if tentative:
            # Ensure candidate defines all public members of the interface
            for name in dir(iface):
                if not name.startswith('_'):
                    if not hasattr(candidate, name):
