    # If iface uses abstract methods (from abc.ABC), ensure they exist in candidate
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    for name in abstract_methods:
        if not hasattr(cls, name):
            if tentative:
                return False
            raise AttributeError(f"{cls.__name__!r} is missing required abstract method '{name}' from interface {iface.__name__!r}")

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    # Gather metaclasses from bases
    metaclasses = []
    for b in bases:
        m = type(b)
        if m is not type:
            metaclasses.append(m)

    if not metaclasses:
        return type

    if len(set(metaclasses)) == 1:
        return metaclasses[0]

    # If multiple metaclasses, find the most derived that is a subclass of all others
    for m in metaclasses:
        if all(issubclass(m, other) for other in metaclasses):
            return m

    raise TypeError('metaclass conflict, no base class found that satisfies all given metaclasses')

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass was provided, use that.
    if explicit_mc is not None:
        return explicit_mc

    # No bases: default to 'type'.
    if not bases:
        return type

    # Start with metaclass of the first base.
    metaclass = type(bases[0])

    # Iterate over the remaining bases and merge metaclasses.
    for base in bases[1:]:
        candidate = type(base)

        if candidate is metaclass:
            continue

        if isinstance(candidate, type) and issubclass(candidate, metaclass):
            metaclass = candidate
        elif issubclass(metaclass, candidate):
            # existing metaclass is more derived; keep it
            continue
        else:
            raise TypeError(
                f"metaclass conflict: {candidate} and {metaclass}"
            )

    return metaclass

