def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = [type(b) for b in bases]
    unique_mets = list(set(metaclasses))

    # Helper to check if a metaclass is more derived than all others
    def is_most_derived(candidate, others):
        return all(candidate is o or issubclass(candidate, o) for o in others)

    most = None
    for candidate in unique_mets:
        if is_most_derived(candidate, [o for o in unique_mets if o is not candidate]):
            if most is not None:
                raise TypeError(
                    f"Conflicting metaclasses: {most.__name__} and {candidate.__name__}"
                )
            most = candidate

    if most is None:
        # All metaclasses are inter-superclassed; fallback to the first metaclass
        most = metaclasses[0]

    return most

