def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tag_pattern = re.compile(r'@(\w+)')
    code_pattern = re.compile(r'```.*?```', re.S)
    code_spans = [(m.start(), m.end()) for m in code_pattern.finditer(text)]

    def in_code(position: int) -> bool:
        for start, end in code_spans:
            if start <= position < end:
                return True
        return False

    tags: Set[str] = set()

    if replacer:
        def repl(match):
            pos = match.start()
            if in_code(pos):
                return match.group(0)
            tags.add(match.group(1))
            return replacer(match.group(1))
        new_text = tag_pattern.sub(repl, text)
    else:
        for m in tag_pattern.finditer(text):
            if not in_code(m.start()):
                tags.add(m.group(1))
        new_text = text

    return tags, new_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if not isinstance(text, str):
        return text
    # Regular expression to find URLs or email addresses
    pattern = re.compile(
        r'''(?i)\b(
            (?: https?:// | www\d{0,3}[.] | mailto: )   # protocol
            [^\s<>]+                                   # domain & path
        )'''
    )

    def replace(match):
        url = match.group(0)
        # Ensure href has a protocol
        if url.startswith('www.'):
            href = 'http://' + url
        else:
            href = url if url.startswith(('http://', 'https://', 'mailto:')) else 'http://' + url
        # Return an <a> tag with desired attributes
        return (
            f'<a href="{href}" '
            f'target="_blank" rel="nofollow noreferrer" '
            f'class="linkified">{url}</a>'
        )

    # Substitute all detected links with the formatted <a> tags
    return pattern.sub(replace, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not text:
        return text
    import re

    # Matches http:// or https:// URLs
    url_pattern = re.compile(r'(https?://[^\s<]+)')

    def replace(match):
        url = match.group(0)
        # escape double quotes in URL, if any
        escaped_url = url.replace('"', '&quot;')
        return (
            f'<a href="{escaped_url}" '
            f'target="_blank" rel="noopener noreferrer">{escaped_url}</a>'
        )

    # Replace plain URLs in the text with link tags
    return url_pattern.sub(replace, text)

def fetch_content_type(url: str) -> Optional[str]:
    import urllib.request
    import urllib.error
    try:
        # Send a HEAD request to obtain only headers
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req) as resp:
            # urllib returns a mapping-like object for headers
            return resp.headers.get('Content-Type')
    except (urllib.error.HTTPError, urllib.error.URLError):
        # Any error while fetching means we cannot determine the content type
        return None
    except Exception:
        # Fallback for unforeseen errors
        return None

