def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Parse the document if it's a string
    if isinstance(doc, str):
        try:
            root = etree.fromstring(doc)
        except Exception as e:
            raise ValueError(f"Failed to parse XML document: {e}")
    else:
        root = doc

    # Resolve the signature node
    sig_node = None
    if signature is None:
        # Search for the first Signature element in the document
        sig_node = root.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature')
    else:
        if isinstance(signature, str):
            try:
                sig_node = etree.fromstring(signature)
            except Exception as e:
                raise ValueError(f"Failed to parse signature XML: {e}")
        else:
            sig_node = signature

    if sig_node is None:
        raise ValueError("No Signature element found to verify")

    # Create a signing context
    ctx = xmlsec.SignatureContext()
    try:
        key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
    except Exception as e:
        raise ValueError(f"Failed to load public key: {e}")

    ctx.key = key

    # Verify the signature
    try:
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False

def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed author did actually generate this message."""
    import base64
    from cryptography.hazmat.primitives import serialization, hashes
    from cryptography.hazmat.primitives.asymmetric import padding
    from lxml import etree

    # Canonicalise XML document if an Element is supplied
    if isinstance(doc, etree._Element):
        data = etree.tostring(doc, method='c14n', exclusive=True)
    elif isinstance(doc, str):
        data = doc.encode('utf-8')
    else:
        data = doc

    # Load public key (PEM format)
    pub_bytes = public_key.encode() if isinstance(public_key, str) else public_key
    try:
        key = serialization.load_pem_public_key(pub_bytes)
    except Exception as exc:
        raise ValueError("Provided public key is invalid") from exc

    # Decode base64 signature
    try:
        sig_bytes = base64.b64decode(signature)
    except Exception as exc:
        raise ValueError("Signature is not valid base64") from exc

    # Perform verification (assuming RSA-PKCS1v15 with SHA256)
    try:
        key.verify(
            sig_bytes,
            data,
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
    except ValueError:
        # Fall back to XRD (XML) parsing
        try:
            root = ET.fromstring(document)
        except ET.ParseError as exc:
            raise ValueError("Input is neither valid JSON nor XRD XML") from exc

        def strip_ns(tag):
            return tag.split('}', 1)[-1] if '}' in tag else tag

        subject = None
        aliases = []
        links = []

        for child in root:
            tag = strip_ns(child.tag)
            if tag == 'Subject':
                subject = child.text
            elif tag == 'Alias':
                aliases.append(child.text)
            elif tag == 'Link':
                rel = child.attrib.get('rel')
                link_type = None
                href = None
                for sub in child:
                    subtag = strip_ns(sub.tag)
                    if subtag == 'Type':
                        link_type = sub.text
                    elif subtag == 'Href':
                        href = sub.text
                links.append({'rel': rel, 'type': link_type, 'href': href})

        data = {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }

    # Ensure required keys exist
    subject = data.get('subject')
    aliases = data.get('aliases', [])
    links = data.get('links', [])

    return {
        'subject': subject,
        'aliases': aliases,
        'links': links
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    document = document.strip()
    if not document:
        raise ValueError("Empty document provided")

    # Try JSON first
    try:
        if document.startswith('{'):
            data = json.loads(document)
            # The new format is already a dict; return as is
            return data
    except Exception:
        pass  # Not JSON, will attempt XML

    # Parse XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XRD XML: {e}")

    namespace = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

    result: Dict = {}

    # Extract Subject
    subject_elem = root.find('xrd:Subject', namespace)
    if subject_elem is not None:
        result['subject'] = subject_elem.text

    # Extract Links
    links = []
    for link_elem in root.findall('xrd:Link', namespace):
        link = {
            'href': link_elem.attrib.get('href'),
            'rel': link_elem.attrib.get('rel'),
            'type': link_elem.attrib.get('type')
        }
        links.append(link)
    if links:
        result['links'] = links

    if not result:
        raise ValueError("Could not parse Diaspora webfinger: unsupported format")

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try JSON first
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass  # fall through to XML parsing

    # Try XRD (XML) format
    try:
        root = ET.fromstring(document)
    except ET.ParseError as exc:
        raise ValueError("Input is not valid JSON or XRD XML") from exc

    # Namespace handling
    ns = ''
    if root.tag.startswith('{'):
        ns_end = root.tag.find('}')
        ns = root.tag[1:ns_end]
    def q(name):
        return f'{{{ns}}}{name}' if ns else name

    result: Dict[str, any] = {}

    # Extract subject
    subject_elem = root.find('.//' + q('subject'))
    if subject_elem is not None and subject_elem.text:
        result['subject'] = subject_elem.text.strip()

    # Extract links
    links = []
    for link in root.findall('.//' + q('link')):
        link_info: Dict[str, str] = {}
        for attr in ('rel', 'type', 'href', 'template'):
            if attr in link.attrib:
                link_info[attr] = link.attrib[attr]
        if link_info:
            links.append(link_info)
    if links:
        result['links'] = links

    # Extract properties
    properties: Dict[str, str] = {}
    for prop in root.findall('.//' + q('property')):
        term = prop.attrib.get('term')
        if term:
            properties[term] = prop.text.strip() if prop.text else ''
    if properties:
        result['properties'] = properties

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    doc = document.strip()
    # Try parsing as JSON
    try:
        data = json.loads(doc)
        return {
            "subject": data.get("subject"),
            "aliases": data.get("aliases", []),
            "properties": data.get("properties", {}),
            "links": data.get("links", []),
        }
    except json.JSONDecodeError:
        # Fall back to XRD (XML) parsing
        try:
            root = ET.fromstring(doc)
        except ET.ParseError as exc:
            raise ValueError("Document is neither valid JSON nor XML XRD") from exc

        # Helper to find element with any namespace
        def find(elem, tag):
            return elem.find(f"{{*}}{tag}")

        def findall(elem, tag):
            return elem.findall(f"{{*}}{tag}")

        subject_elem = find(root, "Subject")
        subject = subject_elem.text if subject_elem is not None else None

        aliases = []
        for alt in findall(root, "Alt"):
            for uri in findall(alt, "URI"):
                if uri.text:
                    aliases.append(uri.text)

        properties = {}
        for prop in findall(root, "Property"):
            name = prop.attrib.get("name")
            if name:
                properties[name] = prop.text

        links = []
        for link in findall(root, "Link"):
            href = link.attrib.get("href")
            rel = link.attrib.get("rel")
            type_ = link.attrib.get("type")
            links.append({"href": href, "rel": rel, "type": type_})

        return {
            "subject": subject,
            "aliases": aliases,
            "properties": properties,
            "links": links,
        }

