def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import urllib.request
    import urllib.parse
    try:
        # Normalize resource parameter
        resource = handle
        if not resource.startswith("acct:"):
            resource = f"acct:{resource}"
        # Extract domain part
        if "@" not in resource:
            return None
        _, domain = resource.split("@", 1)
        # Construct the WebFinger URL
        url = (
            f"https://{domain}/.well-known/webfinger?"
            f"resource={urllib.parse.quote(resource, safe='')}"
        )
        req = urllib.request.Request(
            url,
            headers={
                "Accept": "application/xrd+json, application/json, */*",
            },
        )
        with urllib.request.urlopen(req, timeout=5) as response:
            return response.read().decode("utf-8")
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Import inside function to keep the module clean
    try:
        import urllib.request
        import urllib.parse
        import urllib.error
    except ImportError:
        # urllib is part of the standard library; this should not happen
        return None

    # Check that the handle contains an '@' separator
    if '@' not in handle:
        return None

    try:
        # Build the WebFinger query URL
        user, domain = handle.split('@', 1)
        resource = urllib.parse.quote(f'acct:{handle}')
        url = f'https://{domain}/.well-known/webfinger?resource={resource}'

        # Perform the HTTP GET request with a timeout
        with urllib.request.urlopen(url, timeout=5) as resp:
            data = resp.read()
            # Decode bytes to string assuming UTF-8; fallback to ISO-8859-1 if necessary
            try:
                return data.decode('utf-8')
            except UnicodeDecodeError:
                return data.decode('iso-8859-1')
    except (urllib.error.HTTPError, urllib.error.URLError, ValueError):
        # Any failure (network error, invalid URL, decode error) returns None
        return None
    except Exception:
        # Catch any other unexpected exception to ensure the function never raises
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if '@' not in handle:
        raise ValueError("Handle must be in the form user@host")
    user, host = handle.split('@', 1)
    resource = f"acct:{handle}"
    url = f"https://{host}/.well-known/webfinger?resource={resource}"
    try:
        import requests
        resp = requests.get(url, timeout=10)
        resp.raise_for_status()
    except Exception as exc:
        raise RuntimeError(f"Failed to fetch webfinger document: {exc}") from exc
    # Try to parse as JSON first
    try:
        return resp.json()
    except ValueError:
        # Fallback to XML parsing
        import xml.etree.ElementTree as ET
        try:
            root = ET.fromstring(resp.text)
        except ET.ParseError as exc:
            raise RuntimeError(f"Invalid XML response: {exc}") from exc

        def _elem_to_dict(elem):
            d = {}
            if elem.attrib:
                d.update(elem.attrib)
            children = list(elem)
            if children:
                for child in children:
                    d.setdefault(child.tag, []).append(_elem_to_dict(child))
            else:
                d[elem.tag] = elem.text
            return d

        return _elem_to_dict(root)

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    from xml.etree import ElementTree as ET

    url = f"https://{host}/.well-known/xrd.xml"
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            data = response.read()
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Failed to retrieve host-meta from {host!r}: {exc}") from exc

    try:
        return ET.fromstring(data)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML received from {host!r}") from exc

