def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names in the given directories that match the spec_option.

    Parameters:
        settings_dirs (list of str): Directories to search for files.
        spec_option (str or None): Optional file extension (without dot) or glob pattern to filter files.

    Returns:
        list of str: Full file paths matching the specified option, sorted alphabetically.
    """
    import os
    file_list = []
    # Normalize spec_option: if it ends with a dot, strip it
    if isinstance(spec_option, str):
        spec_pattern = spec_option.strip().lower()
        if spec_pattern.startswith('.'):
            spec_pattern = spec_pattern[1:]
    else:
        spec_pattern = None

    for dir_path in settings_dirs:
        # Skip non-existent directories to avoid errors
        if not os.path.isdir(dir_path):
            continue
        for root, dirs, files in os.walk(dir_path):
            for fname in files:
                full_path = os.path.join(root, fname)
                if spec_pattern:
                    # Check extension match (case-insensitive)
                    ext = os.path.splitext(fname)[1]
