def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        return parser_dict

    includes = parser_dict.get("include")
    if not includes:
        return parser_dict

    if isinstance(includes, str):
        includes = [includes]
    elif isinstance(includes, list):
        # ensure every element is a string
        includes = [i for i in includes if isinstance(i, str)]
    else:
        raise TypeError(f"'include' must be a string or list of strings, got {type(includes).__name__}")

    # Remove the include key so it doesn't appear at the top level
    parser_dict = {k: v for k, v in parser_dict.items() if k != "include"}

    merged = {}
    for name in includes:
        if not hasattr(self, "groups"):
            raise AttributeError("self does not have 'groups' attribute to resolve includes")
        group = self.groups.get(name)
        if group is None:
            raise KeyError(f"Include group '{name}' not found in specification")
        if not isinstance(group, dict):
            raise ValueError(f"Including group '{name}' is expected to be a dict but got {type(group).__name__}")
        merged.update(group)

    # Merge into the current parser_dict, but keep existing keys
    for k, v in merged.items():
        if k not in parser_dict:
            parser_dict[k] = v

    return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Helper to recursively resolve includes
        def _resolve(group_name, seen):
            if group_name in seen:
                raise ValueError(f"Circular include detected: {' -> '.join(seen + [group_name])}")
            seen.append(group_name)
            group = parser_dict.get(group_name)
            if group is None:
                raise KeyError(f"Included group '{group_name}' not found in parser_dict")
            included_names = group.get("include")
            if not included_names:
                return {}
            if isinstance(included_names, str):
                included_names = [included_names]
            merged = {}
            for inc_name in included_names:
                inc_group = parser_dict.get(inc_name)
                if inc_group is None:
                    raise KeyError(f"Included group '{inc_name}' not found in parser_dict")
                # Recursively resolve nested includes
                merged.update(_resolve(inc_name, seen.copy()))
                # Merge the actual include group (after its own includes resolved)
                merged.update({k: v for k, v in inc_group.items() if k != "include"})
            return merged

        # Resolve includes for each top-level group
        for name, group in list(parser_dict.items()):
            if "include" in group:
                merged_content = _resolve(name, [])
                # Update group with merged content, then remove the include key
                group.update(merged_content)
                del group["include"]
        return parser_dict

