        if isinstance(val, str):
            # split on commas, strip spaces
            return [item.strip() for item in val.split(',')]
        return list(val) if val is not None else []

    # Map common alias keys to either conversion functions or use conversion mapping
    for key, current_val in list(values_dict.items()):
        # Use conversion mapping if present
        if key in conversions:
            try:
                values_dict[key] = conversions[key](current_val)
            except Exception:
                # If conversion fails, leave original string
                pass
            continue

        # Apply generic heuristics
        # Try integer conversion
        int_val = _to_int(current_val)
        if int_val != current_val:
            values_dict[key] = int_val
            continue

        # Try float conversion
        float_val = _to_float(current_val)
        if float_val != current_val:
            values_dict[key] = float_val
            continue

        # Try boolean conversion
        bool_val = _to_bool(current_val)
        if bool_val != current_val:
            values_dict[key] = bool_val
            continue

        # Try list conversion if comma separated
        if isinstance(current_val, str) and ',' in current_val:
